    #[test]
    fn what_another_compiler_writes_translates_and_holds_up() {
        let directory = temp_directory("omni-javac");
        let out = directory.join("out");
        std::fs::create_dir_all(&out).unwrap();
        let source = directory.join("Written.java");
        std::fs::write(&source, WHAT_JAVAC_WRITES.trim_start()).unwrap();

        let done = std::process::Command::new("javac")
            .args(["--release", "17", "-d"])
            .arg(out.to_str().unwrap())
            .arg(source.to_str().unwrap())
            .output();
        let Ok(done) = done else {
            std::fs::remove_dir_all(&directory).ok();
            assert!(
                std::env::var("OMNI_REQUIRE_JAVAC").is_err(),
                "OMNI_REQUIRE_JAVAC is set but javac is not here"
            );
            eprintln!("javac conformance: javac is not available here");
            return;
        };
        assert!(
            done.status.success(),
            "javac refused its own source: {}",
            String::from_utf8_lossy(&done.stderr)
        );

        let mut written = Vec::new();
        gather_class_files(&out, &mut written);
        written.sort();
        assert!(!written.is_empty(), "javac wrote nothing");

        let mut refused = Vec::new();
        let mut joined = 0;
        let mut every: Vec<crate::dexwrite::Class> = Vec::new();
        for path in &written {
            let bytes = std::fs::read(path).unwrap();
            let class = crate::jvm::read(&bytes)
                .unwrap_or_else(|error| panic!("{} does not read: {error:?}", path.display()));
            let translated = crate::dalvik::translate_class(&class)
                .unwrap_or_else(|error| panic!("{} does not translate: {error:?}", path.display()));
            for one in &translated {
                refused.extend(what_the_runtime_would_refuse(one));
            }
            every.extend(translated.iter().cloned());

            for method in translated
                .iter()
                .flat_map(|one| one.direct_methods.iter().chain(one.virtual_methods.iter()))
            {
                let wanted: &[&str] = match method.reference.name.as_str() {
                    "joined" => &[
                        "\"a=\"",
                        "Ljava/lang/String;",
                        "I",
                        "\" b=\"",
                        "Ljava/lang/String;",
                        "J",
                        "\" c=\"",
                        "Ljava/lang/String;",
                        "D",
                        "\" d=\"",
                        "Ljava/lang/String;",
                        "Ljava/lang/String;",
                        "\" e=\"",
                        "Ljava/lang/String;",
                        "Ljava/lang/String;",
                        "\" f=\"",
                        "Ljava/lang/String;",
                        "C",
                        "\" g=\"",
                        "Ljava/lang/String;",
                        "Z",
                        "\"!\"",
                        "Ljava/lang/String;",
                    ],
                    "joined_only_values" => &["Ljava/lang/String;", "Ljava/lang/String;"],
                    _ => continue,
                };
                assert_eq!(
                    pieces_of(method),
                    wanted,
                    "{} is not joined the way it was written",
                    method.reference.name
                );
                joined += 1;
            }
        }
        assert!(
            refused.is_empty(),
            "the runtime would refuse this:\n  {}",
            refused.join("\n  ")
        );
        assert_eq!(joined, 2, "both joined strings were read");

        let names: Vec<&str> = every
            .iter()
            .map(|one| one.descriptor.as_str())
            .filter(|one| one.contains("$$Lambda$"))
            .collect();
        assert!(
            names.len() >= 10,
            "a lambda for each one written: {names:?}"
        );

        let by_interface = |wanted: &str| -> &crate::dexwrite::Class {
            every
                .iter()
                .find(|one| one.interfaces.iter().any(|held| held == wanted))
                .unwrap_or_else(|| panic!("nothing implements {wanted}"))
        };

        let counted = by_interface("Lcom/my/app/Written$Counted;");
        assert!(
            counted.instance_fields.is_empty(),
            "a method reference that captured nothing keeps nothing"
        );
        let count = counted
            .virtual_methods
            .iter()
            .find(|one| one.reference.name == "count")
            .expect("it has the interface's method");
        assert_eq!(count.reference.parameters, vec!["Ljava/lang/String;"]);
        assert_eq!(count.reference.return_type, "I");

        let erased = by_interface("Ljava/util/function/Function;");
        let apply = erased
            .virtual_methods
            .iter()
            .find(|one| one.reference.name == "apply")
            .expect("it has the interface's method");
        assert_eq!(apply.reference.parameters, vec!["Ljava/lang/Object;"]);
        assert_eq!(apply.reference.return_type, "Ljava/lang/Object;");
        let told: Vec<String> = apply
            .instructions
            .iter()
            .filter_map(|one| match &one.operand {
                crate::dexwrite::Operand::Type(descriptor) => Some(format!("cast {descriptor}")),
                crate::dexwrite::Operand::Method(call) => {
                    Some(format!("{}.{}", call.class, call.name))
                }
                _ => None,
            })
            .collect();
        assert_eq!(
            told,
            vec![
                "cast Ljava/lang/String;",
                "Ljava/lang/String;.length",
                "Ljava/lang/Integer;.valueOf",
            ],
            "the value is cast on the way in and boxed on the way out"
        );

        let dex = crate::dexwrite::write(&every, &[]).expect("the dex is written");
        if let Some((_, held)) = dexdump(&dex) {
            for one in &names {
                assert!(
                    held.iter().any(|found| found == one),
                    "{one} is not in the package: {held:?}"
                );
            }
        }

        let mut told = annotations_in(&dex, "Lcom/my/app/Written;");
        told.sort();
        assert_eq!(
            told,
            vec![
                "class seen Lcom/my/app/Written$Tagged;(also=[text \"a\", text \"b\"], \
                 exact=double 0.5, flag=boolean true, \
                 kind=enum Lcom/my/app/Written$Kind;.FANCY, letter=char 113, \
                 of=class Ljava/lang/String;, order=int 3, rough=float 1.5, \
                 small=byte 7, value=text \"the class\", wide=long 9223372036854775807)",
                "class system Ldalvik/annotation/MemberClasses;(value=[\
                 class Lcom/my/app/Written$Named;, class Lcom/my/app/Written$Counted;, \
                 class Lcom/my/app/Written$Made;, class Lcom/my/app/Written$Boxed;, \
                 class Lcom/my/app/Written$Taken;, class Lcom/my/app/Written$Kind;, \
                 class Lcom/my/app/Written$Tagged;])",
                "field Lcom/my/app/Written;.label seen \
                 Lcom/my/app/Written$Tagged;(value=text \"a field\")",
                "method seen Lcom/my/app/Written$Tagged;(value=text \"a method\")",
                "method system Ldalvik/annotation/Signature;(value=[text \
                 \"()Ljava/util/function/BiFunction<Ljava/lang/Long;Ljava/lang/Long;\
                 Ljava/lang/Long;>;\"])",
                "method system Ldalvik/annotation/Signature;(value=[text \
                 \"()Ljava/util/function/Function<Ljava/lang/String;Ljava/lang/Integer;>;\"])",
                "method system Ldalvik/annotation/Signature;(value=[text \
                 \"(Ljava/lang/String;)Ljava/util/function/Supplier<Ljava/lang/String;>;\"])",
                "parameter seen Lcom/my/app/Written$Tagged;(value=text \"a parameter\")",
            ],
            "the package does not say what was written on the class"
        );

        let mut nested = annotations_in(&dex, "Lcom/my/app/Written$Tagged;");
        nested.sort();
        assert_eq!(
            nested,
            vec![
                "class seen Ljava/lang/annotation/Retention;(value=enum \
                 Ljava/lang/annotation/RetentionPolicy;.RUNTIME)",
                "class seen Ljava/lang/annotation/Target;(value=[enum \
                 Ljava/lang/annotation/ElementType;.TYPE, enum \
                 Ljava/lang/annotation/ElementType;.FIELD, enum \
                 Ljava/lang/annotation/ElementType;.METHOD, enum \
                 Ljava/lang/annotation/ElementType;.PARAMETER])",
                "class system Ldalvik/annotation/AnnotationDefault;(value=\
                 Lcom/my/app/Written$Tagged;(also=[], exact=double 0, flag=boolean false, \
                 kind=enum Lcom/my/app/Written$Kind;.PLAIN, letter=char 97, \
                 of=class Ljava/lang/Object;, order=int 1, rough=float 0, small=byte 0, \
                 wide=long 0))",
                "class system Ldalvik/annotation/EnclosingClass;(value=class \
                 Lcom/my/app/Written;)",
                "class system Ldalvik/annotation/InnerClass;(accessFlags=int 9737, \
                 name=text \"Tagged\")",
                "method system Ldalvik/annotation/Signature;(value=[text \
                 \"()Ljava/lang/Class<*>;\"])",
            ],
            "the annotation type does not say what it is"
        );

        let mut wanted: Vec<u32> = Vec::new();
        for path in &written {
            let bytes = std::fs::read(path).unwrap();
            let class = crate::jvm::read(&bytes).unwrap();
            for method in &class.methods {
                let Some(code) = &method.code else { continue };
                wanted.extend(code.lines.iter().map(|(_, line)| u32::from(*line)));
            }
        }
        wanted.sort();
        wanted.dedup();
        assert!(wanted.len() > 20, "javac wrote {} lines down", wanted.len());
        if let Some(said) = dexdump_text(&dex) {
            let mut found: Vec<u32> = said
                .lines()
                .filter_map(|line| line.split("line=").nth(1))
                .filter_map(|held| held.trim().parse::<u32>().ok())
                .collect();
            found.sort();
            found.dedup();
            assert_eq!(
                found, wanted,
                "the package does not say the lines the class files said"
            );
        }
        std::fs::remove_dir_all(&directory).ok();
        eprintln!(
            "javac conformance: {} classes another compiler wrote translate and hold up",
            written.len()
        );
    }

    fn pieces_of(method: &crate::dexwrite::Method) -> Vec<String> {
        let mut out = Vec::new();
        for one in &method.instructions {
            match &one.operand {
                crate::dexwrite::Operand::Text(text) => out.push(format!("{text:?}")),
                crate::dexwrite::Operand::Method(call) if call.name == "append" => {
                    out.push(call.parameters.join(","))
                }
                _ => {}
            }
        }
        out
    }

    #[test]
    fn a_new_project_is_given_settings_with_every_key_already_there() {
        let directory = temp_directory("omni-settings-made");
        let root = directory.join("Made");
        let folder = root.to_str().unwrap().to_string();
        crate::scaffold::create(
            &folder,
            &crate::scaffold::Spec {
                package: "com.tr.yt.made".to_string(),
                label: "Made".to_string(),
                languages: vec!["java".to_string()],
                min_sdk: 30,
                target_sdk: 36,
                ..Default::default()
            },
        )
        .expect("the project must be made");

        let written = std::fs::read_to_string(root.join(crate::settings::FILE_NAME))
            .expect("the settings are written beside the manifest");
        for key in [
            "package",
            "namespace",
            "applicationId",
            "label",
            "version",
            "sdk",
            "languages",
            "locales",
            "abis",
            "dependencies",
            "build",
            "java",
            "buildTypes",
            "cmake",
            "proguard",
            "packaging",
            "resources",
            "versions",
            "signing",
        ] {
            assert!(
                written.contains(&format!("\"{key}\"")),
                "{key} is missing: {written}"
            );
        }

        let read = crate::settings::Settings::from_json(&written).expect("they read back");
        assert_eq!(read.package, "com.tr.yt.made");
        assert_eq!(read.min_sdk, 30);
        assert_eq!(read.target_sdk, 36);
        assert!(read.dependencies.is_empty(), "nothing is added by default");
        assert!(read.shrink);
        assert_eq!(read.namespace, "com.tr.yt.made");
        assert_eq!(read.application_id, "com.tr.yt.made");

        assert!(
            written.lines().count() > 40,
            "the settings are written to be read, not on one line: {written}"
        );
        assert!(
            written.contains("\n    \"package\": "),
            "every key sits on its own indented line: {written}"
        );

        let empty = crate::settings::Settings::default();
        for key in ["cppFlags", "excludes", "pickFirst", "named", "plugins"] {
            assert!(
                empty.to_json().contains(&format!("\"{key}\"")),
                "{key} is written even when it holds nothing"
            );
        }

        std::fs::remove_dir_all(&directory).ok();
    }

    #[test]
    fn a_zip_of_a_project_opens_into_one_with_its_wrapper_folder_taken_off() {
        let directory = temp_directory("omni-open-archive");
        std::fs::create_dir_all(&directory).ok();

        let manifest = concat!(
            "<?xml version=\"1.0\" encoding=\"utf-8\"?>\n",
            "<manifest xmlns:android=\"http://schemas.android.com/apk/res/android\"\n",
            "    package=\"com.tr.yt.zipped\"\n",
            "    android:versionCode=\"7\" android:versionName=\"2.1\">\n",
            "    <uses-sdk android:minSdkVersion=\"30\" android:targetSdkVersion=\"36\" />\n",
            "    <application android:label=\"Zipped\" />\n",
            "</manifest>\n"
        );

        let mut packed = crate::archive::Builder::new();
        packed
            .add(
                "Zipped-main/AndroidManifest.xml",
                manifest.as_bytes().to_vec(),
            )
            .expect("the manifest is added");
        packed
            .add(
                "Zipped-main/Java/com/tr/yt/zipped/MainActivity.java",
                b"package com.tr.yt.zipped;\n".to_vec(),
            )
            .expect("a source file is added");
        let bytes = packed.finish().expect("the archive is written");

        let held = directory.join("Zipped.zip");
        std::fs::write(&held, &bytes).expect("the archive lands on disk");
        let root = directory.join("Zipped");

        let opened = crate::workspace::unpack(held.to_str().unwrap(), root.to_str().unwrap(), "")
            .expect("the archive opens into a project");

        assert_eq!(opened.stripped, "Zipped-main/");
        assert_eq!(opened.files, 2);
        assert!(opened.settings_written, "a project it opens gets settings");
        assert!(
            opened.icon_drawn,
            "a project that brought no picture is given one"
        );
        assert!(
            root.join("Res/mipmap-hdpi/ic_launcher.png").is_file(),
            "the picture it was given reaches the launcher folders"
        );
        assert!(
            root.join("AndroidManifest.xml").is_file(),
            "the manifest sits at the root, not inside a wrapper"
        );
        assert!(root
            .join("Java/com/tr/yt/zipped/MainActivity.java")
            .is_file());

        let written = crate::settings::held(root.to_str().unwrap())
            .expect("the settings read")
            .expect("the settings are there");
        assert_eq!(written.package, "com.tr.yt.zipped");
        assert_eq!(written.version_code, 7);
        assert_eq!(written.version_name, "2.1");

        assert!(
            crate::workspace::describe(root.to_str().unwrap()).is_some(),
            "what it wrote is a project this lists"
        );

        std::fs::remove_dir_all(&directory).ok();
    }

    #[test]
    fn a_build_that_would_refuse_says_first_what_it_could_mend() {
        let directory = temp_directory("omni-mendable");
        let root = directory.join("Mend");
        let folder = root.to_str().unwrap().to_string();
        crate::scaffold::create(
            &folder,
            &crate::scaffold::Spec {
                package: "com.tr.yt.mend".to_string(),
                label: "Mend".to_string(),
                languages: vec!["java".to_string()],
                min_sdk: 30,
                target_sdk: 36,
                ..Default::default()
            },
        )
        .expect("the project must be made");

        std::fs::write(
            root.join("Java/App.java"),
            "package com.tr.yt.mend;\n\n\
             public final class App extends Activity {\n\n    \
             @Override\n    protected void onCreate(Bundle state) {\n        \
             super.onCreate(state);\n    }\n}\n",
        )
        .unwrap();

        let held = crate::builder::mendable(&folder);
        assert!(
            !held.repairs.is_empty(),
            "a missing import is something it can mend: {:?}",
            held.left.as_ref().map(|one| one.code.clone())
        );
        assert!(
            held.repairs.iter().all(|one| one.path == "Java/App.java"),
            "every repair names the file it is for: {:?}",
            held.repairs
                .iter()
                .map(|one| one.path.clone())
                .collect::<Vec<_>>()
        );

        let before = std::fs::read_to_string(root.join("Java/App.java")).unwrap();
        assert!(
            !before.contains("import android.app.Activity;"),
            "looking for repairs does not change the project"
        );

        for one in &held.repairs {
            crate::compilers::java_fixer::apply(&folder, one).expect("the repair applies");
        }
        let after = std::fs::read_to_string(root.join("Java/App.java")).unwrap();
        assert!(
            after.contains("import android.app.Activity;"),
            "the import it offered is the one it wrote: {after}"
        );

        let again = crate::builder::mendable(&folder);
        assert!(
            again.repairs.len() < held.repairs.len() || again.clean_enough(),
            "mending leaves less to mend"
        );

        eprintln!(
            "mending: {} repairs offered before a build, none of them applied until asked",
            held.repairs.len()
        );
        std::fs::remove_dir_all(&directory).ok();
    }

