    #[test]
    fn a_byte_array_is_read_by_the_instruction_that_reads_bytes() {
        let source = r#"
public final class Arrays {

    private final byte[] bytes = new byte[4];
    private final boolean[] flags = new boolean[4];

    public int sum(byte[] given) {
        int total = 0;
        for (int at = 0; at < given.length; at = at + 1) {
            total = total + given[at];
        }
        bytes[0] = given[0];
        return total;
    }

    public boolean any(boolean[] given) {
        boolean found = false;
        for (int at = 0; at < given.length; at = at + 1) {
            if (given[at]) {
                found = true;
            }
        }
        flags[0] = given[0];
        return found;
    }
}
"#;
        let classpath = crate::compilers::java::Classpath::new();
        let mut classes = Vec::new();
        for (name, bytes) in
            crate::compilers::java::compile(source.trim_start(), &classpath).expect("it compiles")
        {
            let class = crate::jvm::read(&bytes)
                .unwrap_or_else(|error| panic!("{name} does not read back: {error:?}"));
            classes.extend(crate::dalvik::translate_class(&class).expect("it translates"));
        }

        let opcodes = |wanted: &str| -> Vec<u8> {
            classes
                .iter()
                .flat_map(|one| one.direct_methods.iter().chain(one.virtual_methods.iter()))
                .filter(|one| one.reference.name == wanted)
                .flat_map(|one| one.instructions.iter())
                .filter_map(|one| one.units.first().map(|unit| (unit & 0xff) as u8))
                .collect()
        };

        let over_bytes = opcodes("sum");
        assert!(
            over_bytes.contains(&0x48),
            "a byte array is read with aget-byte: {over_bytes:02x?}"
        );
        assert!(
            over_bytes.contains(&0x4f),
            "a byte array is written with aput-byte: {over_bytes:02x?}"
        );
        assert!(
            !over_bytes.contains(&0x47) && !over_bytes.contains(&0x4e),
            "nothing here touches a byte array as if it held booleans: {over_bytes:02x?}"
        );

        let over_flags = opcodes("any");
        assert!(
            over_flags.contains(&0x47),
            "a boolean array is read with aget-boolean: {over_flags:02x?}"
        );
        assert!(
            over_flags.contains(&0x4e),
            "a boolean array is written with aput-boolean: {over_flags:02x?}"
        );
        assert!(
            !over_flags.contains(&0x48) && !over_flags.contains(&0x4f),
            "nothing here touches a boolean array as if it held bytes: {over_flags:02x?}"
        );

        let sealed = crate::seal::source("com.tr.yt.brick", &"ab".repeat(32));
        let mut guarded = Vec::new();
        for (name, bytes) in
            crate::compilers::java::compile(&sealed, &classpath).expect("the seal compiles")
        {
            let class = crate::jvm::read(&bytes)
                .unwrap_or_else(|error| panic!("{name} does not read back: {error:?}"));
            guarded.extend(crate::dalvik::translate_class(&class).expect("it translates"));
        }
        let over_seal: Vec<u8> = guarded
            .iter()
            .flat_map(|one| one.direct_methods.iter().chain(one.virtual_methods.iter()))
            .filter(|one| one.reference.name == "written")
            .flat_map(|one| one.instructions.iter())
            .filter_map(|one| one.units.first().map(|unit| (unit & 0xff) as u8))
            .collect();
        assert!(
            !over_seal.is_empty(),
            "the seal reads the bytes it was given"
        );
        assert!(
            over_seal.contains(&0x48) && !over_seal.contains(&0x47),
            "the seal compiled into every package reads its bytes as bytes: {over_seal:02x?}"
        );
    }

    #[test]
    fn a_call_up_and_a_call_inward_are_told_apart() {
        let source = r#"
public final class Family {

    static class Elder {
        String greet() {
            return "hello";
        }
    }

    static final class Young extends Elder {

        @Override
        String greet() {
            return super.greet() + hush();
        }

        private String hush() {
            return "!";
        }
    }
}
"#;
        let classpath = crate::compilers::java::Classpath::new();
        let mut classes = Vec::new();
        for (name, bytes) in
            crate::compilers::java::compile(source.trim_start(), &classpath).expect("it compiles")
        {
            let class = crate::jvm::read(&bytes)
                .unwrap_or_else(|error| panic!("{name} does not read back: {error:?}"));
            classes.extend(crate::dalvik::translate_class(&class).expect("it translates"));
        }

        let young = classes
            .iter()
            .find(|one| one.descriptor.ends_with("Young;"))
            .expect("the younger class is there");

        assert!(
            young
                .virtual_methods
                .iter()
                .any(|one| one.reference.name == "greet"),
            "the method that is overridden is a virtual one"
        );
        assert!(
            young
                .direct_methods
                .iter()
                .any(|one| one.reference.name == "hush"),
            "the method that is private is a direct one"
        );

        let greet = young
            .virtual_methods
            .iter()
            .find(|one| one.reference.name == "greet")
            .expect("it is written out");
        let calls: Vec<(String, u8)> = greet
            .instructions
            .iter()
            .filter_map(|one| match &one.operand {
                crate::dexwrite::Operand::Method(reference) => Some((
                    reference.name.clone(),
                    (one.units.first().copied().unwrap_or_default() & 0xff) as u8,
                )),
                _ => None,
            })
            .collect();

        assert!(
            calls.contains(&("greet".to_string(), 0x6f)),
            "a call up into the superclass is invoke-super: {calls:02x?}"
        );
        assert!(
            !calls.contains(&("greet".to_string(), 0x70)),
            "a call up into the superclass is not invoke-direct: {calls:02x?}"
        );
        assert!(
            calls.contains(&("hush".to_string(), 0x70)),
            "a call to a private method is invoke-direct: {calls:02x?}"
        );
        assert!(
            !calls.contains(&("hush".to_string(), 0x6e)),
            "a call to a private method is not invoke-virtual: {calls:02x?}"
        );

        let dex = crate::dexwrite::write(&classes, &[]).expect("it writes");
        crate::dex::integrity(&dex).expect("the file is whole");
    }

    #[test]
    fn a_constant_a_class_declares_reaches_the_package_it_is_written_into() {
        let classpath = crate::compilers::java::Classpath::new();
        let fingerprint = "ab".repeat(32).to_uppercase();
        let sealed = crate::seal::source("com.tr.yt.brick", &fingerprint);
        let mut classes = Vec::new();
        for (name, bytes) in crate::compilers::java::compile(&sealed, &classpath).expect("compiles")
        {
            let class = crate::jvm::read(&bytes)
                .unwrap_or_else(|error| panic!("{name} does not read back: {error:?}"));
            let held = class
                .fields
                .iter()
                .find(|one| one.name == "MADE_BY")
                .expect("the seal declares what made it");
            assert_eq!(
                held.constant,
                Some(crate::jvm::Element::Text(fingerprint.clone())),
                "the class file carries the value"
            );
            classes.extend(crate::dalvik::translate_class(&class).expect("it translates"));
        }

        let dex = crate::dexwrite::write(&classes, &[]).expect("it writes");
        crate::dex::integrity(&dex).expect("the file is whole");

        let at = |where_at: usize| -> u32 {
            u32::from_le_bytes(dex[where_at..where_at + 4].try_into().unwrap())
        };
        let how_many = at(0x60) as usize;
        let class_defs = at(0x64) as usize;
        assert!(how_many > 0, "there is a class");
        let mut with_values = 0;
        for index in 0..how_many {
            if at(class_defs + index * 32 + 28) != 0 {
                with_values += 1;
            }
        }
        assert_eq!(with_values, 1, "the class points at the values it declares");

        if let Some(said) = dexdump_text(&dex) {
            assert!(
                said.contains(&fingerprint),
                "dexdump reads the value back: {said}"
            );
            assert!(
                said.contains("OmniSeal"),
                "dexdump reads the tag back: {said}"
            );
        }
    }

    #[test]
    fn a_package_carries_as_many_dex_files_as_it_takes() {
        let classpath = crate::compilers::java::Classpath::new();
        let mut classes = Vec::new();
        for source in [A_PROGRAM_THAT_USES_THE_LOT, A_PROGRAM_OF_THE_SUGARED_KIND] {
            for (name, bytes) in crate::compilers::java::compile(source.trim_start(), &classpath)
                .expect("the program compiles")
            {
                let class = crate::jvm::read(&bytes)
                    .unwrap_or_else(|error| panic!("{name} does not read back: {error:?}"));
                classes.extend(crate::dalvik::translate_class(&class).expect("it translates"));
            }
        }
        assert!(classes.len() > 4, "there is something to split");

        let whole = crate::dexwrite::write_all(&classes, &[]).expect("one file");
        assert_eq!(whole.len(), 1, "nothing here needs more than one");

        let mut parts = None;
        for most in [64usize, 80, 96, 112, 128, 160, 192, 224, 256, 320] {
            let Ok(held) = crate::dexwrite::write_all_holding(&classes, &[], most) else {
                continue;
            };
            if held.len() > 1 {
                parts = Some(held);
                break;
            }
        }
        let parts = parts.expect("some wall these classes run into");
        assert!(parts.len() > 1, "only {} files came out", parts.len());

        let mut held: Vec<String> = Vec::new();
        for (which, one) in parts.iter().enumerate() {
            let mut sink = crate::diag::Sink::new();
            let read = crate::dex::read(one, &mut sink).expect("each one reads back");
            assert!(!sink.has_blocking(), "{:?}", sink.entries());
            let whole = crate::dex::integrity(one).expect("each one is whole");
            assert!(
                whole.self_consistent(),
                "{} does not check out",
                crate::dexwrite::dex_named(which)
            );
            held.extend(read.class_names().iter().map(|name| name.to_string()));
        }

        let mut wanted: Vec<String> = classes
            .iter()
            .map(|one| crate::dex::descriptor_to_source(&one.descriptor))
            .collect();
        wanted.sort();
        held.sort();
        assert_eq!(held, wanted, "every class is in exactly one of the files");

        assert_eq!(crate::dexwrite::dex_named(0), "classes.dex");
        assert_eq!(crate::dexwrite::dex_named(1), "classes2.dex");
        assert_eq!(crate::dexwrite::dex_named(9), "classes10.dex");

        if let Some((_, names)) = dexdump(&parts[1]) {
            assert!(!names.is_empty(), "dexdump reads the second one too");
        }
        eprintln!(
            "multidex: {} classes across {} files that all read back",
            classes.len(),
            parts.len()
        );
    }

    struct Reading<'a> {
        bytes: &'a [u8],
        strings: usize,
        types: usize,
        fields: usize,
    }

    impl Reading<'_> {
        fn word(&self, at: usize) -> u32 {
            u32::from_le_bytes([
                self.bytes[at],
                self.bytes[at + 1],
                self.bytes[at + 2],
                self.bytes[at + 3],
            ])
        }

        fn uleb(&self, at: &mut usize) -> u32 {
            let mut held = 0u32;
            let mut shift = 0;
            loop {
                let byte = self.bytes[*at];
                *at += 1;
                held |= u32::from(byte & 0x7f) << shift;
                if byte & 0x80 == 0 {
                    return held;
                }
                shift += 7;
            }
        }

        fn text(&self, index: u32) -> String {
            let mut at = self.word(self.strings + index as usize * 4) as usize;
            let _ = self.uleb(&mut at);
            let end = self.bytes[at..].iter().position(|one| *one == 0).unwrap() + at;
            String::from_utf8_lossy(&self.bytes[at..end]).to_string()
        }

        fn named(&self, index: u32) -> String {
            self.text(self.word(self.types + index as usize * 4))
        }

        fn field_named(&self, index: u32) -> String {
            let at = self.fields + index as usize * 8;
            let class = u16::from_le_bytes([self.bytes[at], self.bytes[at + 1]]);
            format!(
                "{}.{}",
                self.named(u32::from(class)),
                self.text(self.word(at + 4))
            )
        }

        fn value(&self, at: &mut usize) -> String {
            let head = self.bytes[*at];
            *at += 1;
            let kind = head & 0x1f;
            let width = usize::from(head >> 5) + 1;
            let mut number = 0u64;
            if !matches!(kind, 0x1c..=0x1f) {
                for step in 0..width {
                    number |= u64::from(self.bytes[*at + step]) << (step * 8);
                }
                *at += width;
            }
            match kind {
                0x00 => format!("byte {}", number as u8 as i8),
                0x02 => format!("short {}", number as u16 as i16),
                0x03 => format!("char {}", number as u16),
                0x04 => format!("int {}", number as u32 as i32),
                0x06 => format!("long {}", number as i64),
                0x10 => format!("float {}", f32::from_bits(number as u32)),
                0x11 => format!("double {}", f64::from_bits(number)),
                0x17 => format!("text {:?}", self.text(number as u32)),
                0x18 => format!("class {}", self.named(number as u32)),
                0x1b => format!("enum {}", self.field_named(number as u32)),
                0x1c => {
                    let held = self.uleb(at);
                    let mut parts = Vec::new();
                    for _ in 0..held {
                        parts.push(self.value(at));
                    }
                    format!("[{}]", parts.join(", "))
                }
                0x1d => self.annotation(at),
                0x1e => "null".to_string(),
                0x1f => format!("boolean {}", head >> 5 != 0),
                other => format!("kind {other:#04x}"),
            }
        }

        fn annotation(&self, at: &mut usize) -> String {
            let kind = self.named(self.uleb(at));
            let count = self.uleb(at);
            let mut parts = Vec::new();
            for _ in 0..count {
                let name = self.text(self.uleb(at));
                parts.push(format!("{name}={}", self.value(at)));
            }
            format!("{kind}({})", parts.join(", "))
        }
    }

    fn annotations_in(bytes: &[u8], wanted: &str) -> Vec<String> {
        let reading = Reading {
            bytes,
            strings: u32::from_le_bytes([bytes[60], bytes[61], bytes[62], bytes[63]]) as usize,
            types: u32::from_le_bytes([bytes[68], bytes[69], bytes[70], bytes[71]]) as usize,
            fields: u32::from_le_bytes([bytes[84], bytes[85], bytes[86], bytes[87]]) as usize,
        };
        let class_defs_size = reading.word(96) as usize;
        let class_defs_off = reading.word(100) as usize;

        let mut out = Vec::new();
        for index in 0..class_defs_size {
            let row = class_defs_off + index * 32;
            if reading.named(reading.word(row)) != wanted {
                continue;
            }
            let directory = reading.word(row + 20) as usize;
            if directory == 0 {
                return out;
            }
            let on_the_class = reading.word(directory) as usize;
            let fields = reading.word(directory + 4) as usize;
            let methods = reading.word(directory + 8) as usize;
            let parameters = reading.word(directory + 12) as usize;

            let mut sets: Vec<(String, usize)> = Vec::new();
            if on_the_class != 0 {
                sets.push(("class".to_string(), on_the_class));
            }
            let mut walk = directory + 16;
            for _ in 0..fields {
                sets.push((
                    format!("field {}", reading.field_named(reading.word(walk))),
                    reading.word(walk + 4) as usize,
                ));
                walk += 8;
            }
            for _ in 0..methods {
                sets.push(("method".to_string(), reading.word(walk + 4) as usize));
                walk += 8;
            }
            for _ in 0..parameters {
                let list = reading.word(walk + 4) as usize;
                let held = reading.word(list) as usize;
                for step in 0..held {
                    let at = reading.word(list + 4 + step * 4) as usize;
                    if at != 0 {
                        sets.push(("parameter".to_string(), at));
                    }
                }
                walk += 8;
            }

            for (what, set) in sets {
                let held = reading.word(set) as usize;
                for step in 0..held {
                    let mut at = reading.word(set + 4 + step * 4) as usize;
                    let visibility = bytes[at];
                    at += 1;
                    out.push(format!(
                        "{what} {} {}",
                        match visibility {
                            1 => "seen",
                            2 => "system",
                            _ => "unseen",
                        },
                        reading.annotation(&mut at)
                    ));
                }
            }
        }
        out
    }

    #[test]
    fn nestmates_and_monitors_come_out_the_way_art_accepts_them() {
        let directory = temp_directory("omni-nests");
        let made = directory.join("classes");
        std::fs::create_dir_all(made.join("nest")).unwrap();
        std::fs::write(
            directory.join("Outer.java"),
            r#"
package nest;

public class Outer {
    private int count;

    private static int hidden() {
        return 7;
    }

    private String secret(long wide, int n) {
        return "s" + wide + n + count;
    }

    public synchronized int guarded() {
        return count;
    }

    public int locked(Object on) {
        synchronized (on) {
            return count + 1;
        }
    }

    public final class Inner {
        public String peek() {
            count++;
            return secret(5L, 2) + hidden();
        }
    }
}
"#
            .trim_start(),
        )
        .unwrap();
        let done = std::process::Command::new("javac")
            .args(["--release", "17", "-d"])
            .arg(made.to_str().unwrap())
            .arg(directory.join("Outer.java").to_str().unwrap())
            .output();
        let Ok(done) = done else {
            std::fs::remove_dir_all(&directory).ok();
            assert!(
                std::env::var("OMNI_REQUIRE_JAVAC").is_err(),
                "OMNI_REQUIRE_JAVAC is set but javac is not here"
            );
            eprintln!("nests: javac is not available here");
            return;
        };
        assert!(
            done.status.success(),
            "{}",
            String::from_utf8_lossy(&done.stderr)
        );

        let mut files = Vec::new();
        gather_class_files(&made, &mut files);
        files.sort();
        let mut classes = Vec::new();
        for path in &files {
            let class =
                crate::jvm::read(&std::fs::read(path).unwrap()).expect("javac's class reads");
            classes.extend(crate::dalvik::translate_class(&class).expect("and translates"));
        }
        let classes = crate::dalvik::open_nests(classes);

        let outer = classes
            .iter()
            .find(|one| one.descriptor == "Lnest/Outer;")
            .expect("the outer class");
        let inner = classes
            .iter()
            .find(|one| one.descriptor == "Lnest/Outer$Inner;")
            .expect("the inner class");

        let bridge_name = format!("{}secret", crate::dalvik::NEST_BRIDGE);
        let bridge = outer
            .direct_methods
            .iter()
            .find(|one| one.reference.name == bridge_name)
            .expect("the private method another class calls gets a bridge");
        assert!(bridge.access_flags & 0x0008 != 0, "the bridge is static");
        assert_eq!(bridge.reference.parameters, vec!["Lnest/Outer;", "J", "I"]);
        assert_eq!(bridge.inputs, 4, "the receiver, a long in two, and an int");

        let calls: Vec<(u16, String)> = inner
            .direct_methods
            .iter()
            .chain(inner.virtual_methods.iter())
            .flat_map(|one| one.instructions.iter())
            .filter_map(|one| match &one.operand {
                crate::dexwrite::Operand::Method(called) => {
                    Some((one.units[0] & 0xff, called.name.clone()))
                }
                _ => None,
            })
            .collect();
        assert!(
            calls
                .iter()
                .any(|(opcode, name)| (*opcode == 0x71 || *opcode == 0x77) && *name == bridge_name),
            "{calls:?}"
        );
        assert!(!calls.iter().any(|(_, name)| name == "secret"), "{calls:?}");

        let private = |flags: u32| flags & 0x0002 != 0;
        let count = outer
            .instance_fields
            .iter()
            .find(|one| one.reference.name == "count")
            .unwrap();
        assert!(
            !private(count.access_flags),
            "a field another class touches is opened"
        );
        let hidden = outer
            .direct_methods
            .iter()
            .find(|one| one.reference.name == "hidden")
            .unwrap();
        assert!(
            !private(hidden.access_flags),
            "a static method another class calls is opened"
        );

        let guarded = outer
            .virtual_methods
            .iter()
            .find(|one| one.reference.name == "guarded")
            .unwrap();
        assert_eq!(
            guarded.access_flags & 0x0020,
            0,
            "ACC_SYNCHRONIZED is not a dex flag"
        );
        assert!(guarded.access_flags & crate::dexwrite::ACC_DECLARED_SYNCHRONIZED != 0);
        let opcodes: Vec<u16> = guarded
            .instructions
            .iter()
            .filter_map(|one| one.units.first().map(|unit| unit & 0xff))
            .collect();
        assert!(
            opcodes.contains(&0x1d) && opcodes.contains(&0x1e),
            "{opcodes:02x?}"
        );
        assert!(
            guarded
                .tries
                .iter()
                .any(|one| one.catches.iter().any(|(caught, _)| caught.is_none())),
            "the monitor is let go on the way out of an exception too"
        );
        for class in &classes {
            for one in &class.direct_methods {
                if one.reference.name == "<init>" || one.reference.name == "<clinit>" {
                    assert!(one.access_flags & crate::dexwrite::ACC_CONSTRUCTOR != 0);
                }
            }
        }

        let dex = crate::dexwrite::write(&classes, &[]).expect("the dex is written");
        if let Some(said) = dexdump_text(&dex) {
            assert!(said.contains(&bridge_name), "dexdump reads the bridge back");
        }
        eprintln!("nests: a bridge, opened members and held monitors");
        std::fs::remove_dir_all(&directory).ok();
    }

    #[test]
    fn library_manifests_merge_the_way_the_manifest_merger_merges_them() {
        let application = r#"<?xml version="1.0" encoding="utf-8"?>
<manifest xmlns:android="http://schemas.android.com/apk/res/android"
    xmlns:tools="http://schemas.android.com/tools"
    package="com.tr.shapes">
    <application android:label="Shapes" tools:replace="android:label">
        <activity android:name=".Main" android:exported="true" />
        <provider
            android:name="androidx.startup.InitializationProvider"
            android:authorities="${applicationId}.androidx-startup"
            tools:node="merge">
            <meta-data
                android:name="androidx.emoji2.text.EmojiCompatInitializer"
                tools:node="remove" />
        </provider>
    </application>
</manifest>"#;
        let emoji = r#"<manifest xmlns:android="http://schemas.android.com/apk/res/android"
    xmlns:tools="http://schemas.android.com/tools" package="androidx.emoji2">
    <uses-sdk android:minSdkVersion="19" />
    <application android:label="not this one">
        <provider
            android:name="androidx.startup.InitializationProvider"
            android:authorities="${applicationId}.androidx-startup"
            android:exported="false"
            tools:node="merge">
            <meta-data
                android:name="androidx.emoji2.text.EmojiCompatInitializer"
                android:value="androidx.startup" />
        </provider>
    </application>
</manifest>"#;
        let lifecycle = r#"<manifest xmlns:android="http://schemas.android.com/apk/res/android"
    xmlns:tools="http://schemas.android.com/tools" package="androidx.lifecycle.process">
    <uses-permission android:name="android.permission.INTERNET" />
    <application>
        <provider
            android:name="androidx.startup.InitializationProvider"
            android:authorities="${applicationId}.androidx-startup"
            android:exported="false"
            tools:node="merge">
            <meta-data
                android:name="androidx.lifecycle.ProcessLifecycleInitializer"
                android:value="androidx.startup" />
        </provider>
        <receiver android:name="x.Told" android:exported="true">
            <intent-filter><action android:name="x.FIRST" /></intent-filter>
            <intent-filter><action android:name="x.SECOND" /></intent-filter>
        </receiver>
    </application>
</manifest>"#;
        let merged = crate::builder::merged_manifest(
            application,
            &[emoji.to_string(), lifecycle.to_string()],
        )
        .expect("the manifests merge");
        assert!(
            !merged.contains("tools:"),
            "nothing the merger reads is left: {merged}"
        );
        assert!(!merged.contains("${applicationId}"), "{merged}");

        let mut sink = crate::diag::Sink::new();
        let root = crate::xml::parse(&merged, "merged", &mut sink).expect("what is merged reads");
        assert!(
            root.children_named("uses-sdk").next().is_none(),
            "a library's floor is not the application's"
        );
        assert!(root
            .children_named("uses-permission")
            .any(|one| one.attribute("android:name") == Some("android.permission.INTERNET")));
        let application = root.children_named("application").next().unwrap();
        assert_eq!(application.attribute("android:label"), Some("Shapes"));

        let providers: Vec<&crate::xml::Element> = application.children_named("provider").collect();
        assert_eq!(
            providers.len(),
            1,
            "one provider, however many libraries name it"
        );
        let provider = providers[0];
        assert_eq!(
            provider.attribute("android:authorities"),
            Some("com.tr.shapes.androidx-startup")
        );
        assert_eq!(provider.attribute("android:exported"), Some("false"));
        let started: Vec<&str> = provider
            .children_named("meta-data")
            .filter_map(|one| one.attribute("android:name"))
            .collect();
        assert_eq!(
            started,
            vec!["androidx.lifecycle.ProcessLifecycleInitializer"],
            "what the application removed stays removed, and the rest is kept"
        );

        let receiver = application
            .children_named("receiver")
            .next()
            .expect("the receiver");
        assert_eq!(
            receiver.children_named("intent-filter").count(),
            2,
            "two filters stay two"
        );
        eprintln!("manifests: merged by name, tools:node honoured, ${{applicationId}} filled");
    }

    fn dexdump_text(bytes: &[u8]) -> Option<String> {
        let tool = find_apksigner().and_then(|p| Some(p.parent()?.join("dexdump")))?;
        if !tool.is_file() {
            return None;
        }
        let directory = temp_directory("dexdump-lines");
        let path = directory.join("classes.dex");
        std::fs::write(&path, bytes).ok()?;
        let output = std::process::Command::new(&tool)
            .args(["-d", path.to_str()?])
            .output()
            .ok()?;
        std::fs::remove_dir_all(&directory).ok();
        output
            .status
            .success()
            .then(|| String::from_utf8_lossy(&output.stdout).to_string())
    }

    fn gather_class_files(root: &std::path::Path, into: &mut Vec<std::path::PathBuf>) {
        let Ok(entries) = std::fs::read_dir(root) else {
            return;
        };
        for entry in entries.flatten() {
            let path = entry.path();
            if path.is_dir() {
                gather_class_files(&path, into);
            } else if path.extension().and_then(|one| one.to_str()) == Some("class") {
                into.push(path);
            }
        }
    }

    fn library_corpus() -> Vec<std::path::PathBuf> {
        let folder = std::env::var("OMNI_LIBRARY_CORPUS")
            .map(std::path::PathBuf::from)
            .unwrap_or_else(|_| {
                std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("target/library-corpus")
            });
        let Ok(entries) = std::fs::read_dir(&folder) else {
            return Vec::new();
        };
        let mut found: Vec<std::path::PathBuf> = entries
            .flatten()
            .map(|entry| entry.path())
            .filter(|path| {
                path.extension()
                    .map(|held| held == "jar" || held == "aar")
                    .unwrap_or(false)
            })
            .collect();
        found.sort();
        found
    }

