        assert!(sink.entries().iter().any(|d| d.code == "EA012"));

        let mut sink = Sink::new();
        assert!(archive::read(&[0u8; 64], &mut sink).is_none());
        assert!(sink.entries().iter().any(|d| d.code == "EA013"));

