    fn android_jar() -> Option<std::path::PathBuf> {
        let platforms = find_apksigner()?
            .parent()?
            .parent()?
            .parent()?
            .join("platforms");
        let mut versions: Vec<std::path::PathBuf> = std::fs::read_dir(platforms)
            .ok()?
            .filter_map(|entry| entry.ok())
            .map(|entry| entry.path())
            .collect();
        versions.sort();
        versions.into_iter().rev().find_map(|version| {
            let jar = version.join("android.jar");
            jar.is_file().then_some(jar)
        })
    }

    fn natural(hex: &str) -> crate::bignum::Natural {
        let padded = if hex.len().is_multiple_of(2) {
            hex.to_string()
        } else {
            format!("0{hex}")
        };
        let bytes: Vec<u8> = (0..padded.len())
            .step_by(2)
            .map(|at| u8::from_str_radix(&padded[at..at + 2], 16).unwrap())
            .collect();
        crate::bignum::Natural::from_bytes_be(&bytes)
    }

    fn hex_of(value: &crate::bignum::Natural) -> String {
        if value.is_zero() {
            return "0".to_string();
        }
        let bytes = value.to_bytes_be(value.byte_len()).unwrap();
        let text: String = bytes.iter().map(|byte| format!("{byte:02x}")).collect();
        text.trim_start_matches('0').to_string()
    }

    #[test]
