    #[test]
    fn this_application_meets_the_policy_it_enforces_on_what_it_builds() {
        let mut candidates: Vec<std::path::PathBuf> = Vec::new();
        for variant in ["release"] {
            for shape in ["merged_manifest", "merged_manifests"] {
                let mut root = std::path::PathBuf::from("Builder/build/intermediates");
                root.push(shape);
                root.push(variant);
                let Ok(entries) = std::fs::read_dir(&root) else {
                    continue;
                };
                for entry in entries.flatten() {
                    let path = entry.path().join("AndroidManifest.xml");
                    if path.is_file() {
                        candidates.push(path);
                    }
                }
            }
        }

        if candidates.is_empty() {
            assert!(
                std::env::var("OMNI_REQUIRE_SELF_POLICY").is_err(),
                "OMNI_REQUIRE_SELF_POLICY is set but no merged manifest was found, so this \
                 application was never held to the policy it enforces on what it builds"
            );
            eprintln!("self policy: no merged manifest has been produced here");
            return;
        }

        const OWN_EXCEPTION: &str = "android.permission.REQUEST_INSTALL_PACKAGES";

        for path in &candidates {
            let text = std::fs::read_to_string(path).unwrap();
            let mut sink = Sink::new();
            let root = crate::xml::parse(&text, "AndroidManifest.xml", &mut sink)
                .unwrap_or_else(|| panic!("{} must parse", path.display()));
            let report = crate::guard::inspect_manifest(&root);

            let unexpected: Vec<String> = report
                .findings
                .iter()
                .filter(|finding| !finding.what.contains(OWN_EXCEPTION))
                .map(|finding| format!("{}: {} {}", finding.code, finding.what, finding.remedy))
                .collect();
            assert!(
                unexpected.is_empty(),
                "{} is refused by the policy this build applies to others:\n{}",
                path.display(),
                unexpected.join("\n")
            );
            assert!(report.rules_applied >= 7);
        }

        let asking = format!(
            "<?xml version=\"1.0\" encoding=\"utf-8\"?>\n\
             <manifest xmlns:android=\"http://schemas.android.com/apk/res/android\" \
             package=\"com.my.app\">\n\
             <uses-permission android:name=\"{OWN_EXCEPTION}\" />\n\
             <application android:label=\"L\" android:allowBackup=\"false\" \
             android:hasCode=\"false\" android:extractNativeLibs=\"false\" />\n\
             </manifest>"
        );
        let mut sink = Sink::new();
        let root = crate::xml::parse(&asking, "AndroidManifest.xml", &mut sink).unwrap();
        let report = crate::guard::inspect_manifest(&root);
        assert_eq!(report.verdict(), crate::guard::Verdict::Refused);
        assert!(
            report
                .findings
                .iter()
                .any(|finding| finding.code == "EG007"),
            "{:?}",
            report.findings
        );

        eprintln!(
            "self policy: {} release manifest(s) of this application pass the rules it \
             enforces, but for {OWN_EXCEPTION}, which it holds so it can install what it \
             builds and which it still refuses in every project. The debug manifest is \
             deliberately not checked: it is marked debuggable, which is what EG001 exists \
             to refuse, and it is never the artifact this build publishes.",
            candidates.len()
        );
    }

    #[test]
    fn a_name_with_xml_in_it_survives_the_manifest_intact() {
        let chosen = "Ali & <Veli> \"Co\"";
        let spec = crate::scaffold::Spec {
            label: chosen.to_string(),
            version_name: "1.0.0".to_string(),
            version_code: 7,
            ..crate::scaffold::Spec::default()
        };
        let text = spec.manifest();
        assert!(text.contains("android:versionCode=\"7\""), "{text}");
        assert!(text.contains("android:versionName=\"1.0.0\""), "{text}");

        let mut sink = Sink::new();
        let root = crate::xml::parse(&text, "AndroidManifest.xml", &mut sink)
            .expect("a name with markup in it must still produce a manifest that reads back");
        assert!(!sink.has_blocking(), "{:?}", sink.entries());
        let application = root
            .children
            .iter()
            .find(|child| child.name == "application")
            .unwrap();
        assert_eq!(
            application.attribute("android:label").unwrap(),
            format!("@string/{}", crate::scaffold::LABEL_RESOURCE),
            "the name lives in the values folders now, so the manifest points at it"
        );

        let mut table = ResourceTable::new();
        let mut sink = Sink::new();
        for (folder, body) in spec.values_files() {
            let config = crate::resources::Config::parse_values_directory(&folder).unwrap();
            assert!(
                table.read_values_for(&body, &folder, config, &mut sink),
                "{:?}",
                sink.entries()
            );
        }
        assert!(!sink.has_blocking(), "{:?}", sink.entries());
        for entry in table.entries() {
            assert_eq!(
                entry.value,
                crate::resources::Value::Text(chosen.to_string()),
                "the markup in the name survives the escaping in {}",
                entry.config
            );
        }
    }

