    #[test]
    fn the_binary_xml_writer_survives_arbitrary_documents() {
        let mut seed = 0x9e37_79b9_7f4a_7c15u64;
        let names = [
            "manifest",
            "application",
            "activity",
            "meta-data",
            "x",
            "\u{00e7}\u{011f}\u{00fc}",
            "\u{1f480}",
        ];
        let values = [
            "true",
            "false",
            "0",
            "-1",
            "0x7f",
            "@0x7f060000",
            "text",
            "",
            "\u{1f480}",
        ];
        let attributes = [
            "android:name",
            "android:exported",
            "package",
            "android:label",
            "other",
        ];

        fn build(
            depth: u32,
            seed: &mut u64,
            names: &[&str],
            values: &[&str],
            attributes: &[&str],
        ) -> crate::xml::Element {
            let pick = |seed: &mut u64, len: usize| (xorshift(seed) as usize) % len;
            let mut element = crate::xml::Element {
                name: names[pick(seed, names.len())].to_string(),
                attributes: Vec::new(),
                children: Vec::new(),
                text: String::new(),
                position: crate::xml::Position { line: 1, column: 1 },
                child_at: Vec::new(),
            };
            for _ in 0..(xorshift(seed) % 5) {
                element.attributes.push(crate::xml::Attribute {
                    name: attributes[pick(seed, attributes.len())].to_string(),
                    value: values[pick(seed, values.len())].to_string(),
                    position: crate::xml::Position { line: 1, column: 1 },
                });
            }
            if depth < 3 {
                for _ in 0..(xorshift(seed) % 3) {
                    element
                        .children
                        .push(build(depth + 1, seed, names, values, attributes));
                }
            }
            element
        }

        for _ in 0..2_000 {
            let root = build(0, &mut seed, &names, &values, &attributes);
            match axml::encode(&root) {
                Ok(bytes) => {
                    assert!(bytes.len() >= 8);
                    assert_eq!(&bytes[0..2], &[0x03, 0x00]);
                }
                Err(error) => assert!(!error.code.is_empty()),
            }
        }
    }

