        fn ToUpperCase(p: &mut [u8]) -> i32 {
            if (fast!((p)[0]) < 0xc0) {
                if (fast!((p)[0]) >= b'a' && fast!((p)[0]) <= b'z') {
                    fast_mut!((p)[0]) ^= 32;
                }
                return 1;
            }

            if (fast!((p)[0]) < 0xe0) {
                fast_mut!((p)[1]) ^= 32;
                return 2;
            }

            fast_mut!((p)[2]) ^= 5;
            3
        }

