                            let offset1: usize =
                                (mixed1 << self.specialization.block_bits()) + num_ref1 as usize;
                            let offset2: usize =
                                (mixed2 << self.specialization.block_bits()) + num_ref2 as usize;
                            let offset3: usize =
                                (mixed3 << self.specialization.block_bits()) + num_ref3 as usize;
