            #[test]
            fn client_mandatory_auth_client_revocation_works() {
                let provider = provider::DEFAULT_PROVIDER;
                for (client_config, _, expect) in
                    MultiTest::new(provider.clone()).require_client_auth()
                {
                    let relevant_crls = vec![expect.key_type.client_crl()];

                    let ee_verifier_builder = webpki_client_verifier_builder(
                        expect.key_type.client_root_store(),
                        &provider,
                    )
                    .with_crls(relevant_crls)
                    .only_check_end_entity_revocation();
                    let revoked_server_config = Arc::new(make_server_config_with_client_verifier(
                        expect.key_type,
                        ee_verifier_builder,
                        &provider,
                    ));

                    let unrelated_crls = vec![expect.key_type.intermediate_crl()];
                    let ee_verifier_builder = webpki_client_verifier_builder(
                        expect.key_type.client_root_store(),
                        &provider,
                    )
                    .with_crls(unrelated_crls.clone())
                    .only_check_end_entity_revocation();
                    let missing_client_crl_server_config =
                        Arc::new(make_server_config_with_client_verifier(
                            expect.key_type,
                            ee_verifier_builder,
                            &provider,
                        ));

                    let ee_verifier_builder = webpki_client_verifier_builder(
                        expect.key_type.client_root_store(),
                        &provider,
                    )
                    .with_crls(unrelated_crls.clone())
                    .only_check_end_entity_revocation()
                    .allow_unknown_revocation_status();
                    let allow_missing_client_crl_server_config =
                        Arc::new(make_server_config_with_client_verifier(
                            expect.key_type,
                            ee_verifier_builder,
                            &provider,
                        ));

                    let mut client_output = Vec::new();
                    let mut server_output = Vec::new();
                    let (mut client, mut server) = make_pair_for_arc_configs(
                        &client_config,
                        &revoked_server_config,
                        &mut client_output,
                    );
                    let mut client_input = VecInput::default();
                    let mut server_input = VecInput::default();
                    let err = do_handshake_until_error(
                        &mut client_input,
                        &mut client_output,
                        &mut client,
                        &mut server_input,
                        &mut server_output,
                        &mut server,
                    );
                    assert_eq!(
                        err,
                        Err(ErrorFromPeer::Server(Error::InvalidCertificate(
                            CertificateError::Revoked
                        )))
                    );

                    let mut client_output = Vec::new();
                    let mut server_output = Vec::new();
                    let (mut client, mut server) = make_pair_for_arc_configs(
                        &client_config,
                        &missing_client_crl_server_config,
                        &mut client_output,
                    );
                    let mut client_input = VecInput::default();
                    let mut server_input = VecInput::default();
                    let res = do_handshake_until_error(
                        &mut client_input,
                        &mut client_output,
                        &mut client,
                        &mut server_input,
                        &mut server_output,
                        &mut server,
                    );
                    assert_eq!(
                        res,
                        Err(ErrorFromPeer::Server(Error::InvalidCertificate(
                            CertificateError::UnknownRevocationStatus
                        )))
                    );

                    let mut client_output = Vec::new();
                    let mut server_output = Vec::new();
                    let (mut client, mut server) = make_pair_for_arc_configs(
                        &client_config,
                        &allow_missing_client_crl_server_config,
                        &mut client_output,
                    );
                    let mut client_input = VecInput::default();
                    let mut server_input = VecInput::default();
                    do_handshake_until_error(
                        &mut client_input,
                        &mut client_output,
                        &mut client,
                        &mut server_input,
                        &mut server_output,
                        &mut server,
                    )
                    .unwrap();
                }
            }

