            #[test]
            fn test_refresh_traffic_keys() {
                let mut client_output = Vec::new();
                let mut server_output = Vec::new();
                let (mut client, mut server) = make_pair(
                    KeyType::default(),
                    &provider::DEFAULT_PROVIDER,
                    &mut client_output,
                );
                let mut client_input = VecInput::default();
                let mut server_input = VecInput::default();
                do_handshake(
                    &mut client_input,
                    &mut client_output,
                    &mut client,
                    &mut server_input,
                    &mut server_output,
                    &mut server,
                );

                fn check_both_directions(
                    client_input: &mut VecInput,
                    client_output: &mut Vec<u8>,
                    client: &mut ClientConnection,
                    server_input: &mut VecInput,
                    server_output: &mut Vec<u8>,
                    server: &mut ServerConnection,
                ) {
                    client.write(b"to-server-1".into(), client_output).unwrap();
                    server.write(b"to-client-1".into(), server_output).unwrap();
                    transfer(client_output, server_input);
                    let server_iter = server.read_tls(server_input, server_output);

                    let mut buf = Vec::with_capacity(16);
                    server_iter.handle_all(&mut buf).unwrap();
                    assert_eq!(&buf, b"to-server-1");

                    transfer(server_output, client_input);
                    let client_iter = client.read_tls(client_input, client_output);

                    let mut buf = Vec::with_capacity(16);
                    client_iter.handle_all(&mut buf).unwrap();
                    assert_eq!(&buf, b"to-client-1");
                }

                check_both_directions(
                    &mut client_input,
                    &mut client_output,
                    &mut client,
                    &mut server_input,
                    &mut server_output,
                    &mut server,
                );
                client.refresh_traffic_keys(&mut client_output).unwrap();
                check_both_directions(
                    &mut client_input,
                    &mut client_output,
                    &mut client,
                    &mut server_input,
                    &mut server_output,
                    &mut server,
                );
                server.refresh_traffic_keys(&mut server_output).unwrap();
                check_both_directions(
                    &mut client_input,
                    &mut client_output,
                    &mut client,
                    &mut server_input,
                    &mut server_output,
                    &mut server,
                );
            }

            #[test]
            fn test_refresh_traffic_keys_is_idempotent() {
                let mut client_output = Vec::new();
                let mut server_output = Vec::new();
                let (mut client, mut server) = make_pair(
                    KeyType::default(),
                    &provider::DEFAULT_PROVIDER,
                    &mut client_output,
                );
                let mut client_input = VecInput::default();
                let mut server_input = VecInput::default();
                do_handshake(
                    &mut client_input,
                    &mut client_output,
                    &mut client,
                    &mut server_input,
                    &mut server_output,
                    &mut server,
                );
                test(
                    &mut client_input,
                    &mut client_output,
                    &mut client,
                    &mut server_input,
                    &mut server_output,
                    &mut server,
                );

                let mut client_output = Vec::new();
                let mut server_output = Vec::new();
                let (mut client, mut server) = make_pair(
                    KeyType::default(),
                    &provider::DEFAULT_PROVIDER,
                    &mut client_output,
                );
                let mut client_input = VecInput::default();
                let mut server_input = VecInput::default();
                do_handshake(
                    &mut client_input,
                    &mut client_output,
                    &mut client,
                    &mut server_input,
                    &mut server_output,
                    &mut server,
                );
                test(
                    &mut server_input,
                    &mut server_output,
                    &mut server,
                    &mut client_input,
                    &mut client_output,
                    &mut client,
                );

                fn test(
                    left_input: &mut VecInput,
                    left_output: &mut Vec<u8>,
                    left: &mut impl Connection,
                    right_input: &mut VecInput,
                    right_output: &mut Vec<u8>,
                    right: &mut impl Connection,
                ) {
                    left.refresh_traffic_keys(left_output).unwrap();
                    assert!(transfer(left_output, right_input) > 0);

                    for _ in 0..5 {
                        left.refresh_traffic_keys(left_output).unwrap();
                        assert_eq!(transfer(left_output, right_input), 0);
                    }

                    right
                        .read_tls(right_input, right_output)
                        .handle_all(&mut Vec::new())
                        .unwrap();
                    right.write(b"yo".into(), right_output).unwrap();
                    assert!(transfer(right_output, left_input) > 0);
                    left.read_tls(left_input, left_output)
                        .handle_all(&mut Vec::new())
                        .unwrap();

                    left.refresh_traffic_keys(left_output).unwrap();
                    assert!(transfer(left_output, right_input) > 0);
                }
            }

            #[test]
            fn test_automatic_refresh_traffic_keys() {
                const fn encrypted_size(body: usize) -> usize {
                    let padding = 1;
                    let header = 5;
                    let tag = 16;
                    header + body + padding + tag
                }

                const KEY_UPDATE_SIZE: usize = encrypted_size(5);
                let provider =
                    aes_128_gcm_with_1024_confidentiality_limit(provider::DEFAULT_PROVIDER);

                let client_config =
                    ClientConfig::builder(provider.clone()).finish(KeyType::default());
                let server_config = ServerConfig::builder(provider).finish(KeyType::default());

                let mut client_output = Vec::new();
                let mut server_output = Vec::new();
                let (mut client, mut server) =
                    make_pair_for_configs(client_config, server_config, &mut client_output);
                let mut client_input = VecInput::default();
                let mut server_input = VecInput::default();
                do_handshake(
                    &mut client_input,
                    &mut client_output,
                    &mut client,
                    &mut server_input,
                    &mut server_output,
                    &mut server,
                );

                for i in 0..(CONFIDENTIALITY_LIMIT + 16) {
                    let message = format!("{i:08}");
                    client
                        .write(message.as_bytes().into(), &mut client_output)
                        .unwrap();
                    let transferred = transfer(&mut client_output, &mut server_input);
                    let iter = server.read_tls(&mut server_input, &mut server_output);
                    let mut buf = Vec::with_capacity(32);
                    let state = iter.handle_all(&mut buf).unwrap();
                    println!("{}: {} -> {:?}", i, transferred, state);

                    assert_eq!(
                        transferred,
                        match i {
                            CONFIDENTIALITY_LIMIT =>
                                KEY_UPDATE_SIZE + encrypted_size(message.len()),
                            _ => encrypted_size(message.len()),
                        }
                    );

                    assert_eq!(&buf, message.as_bytes());
                }

                let message = b"finished";
                server.write(message.into(), &mut server_output).unwrap();
                let transferred = transfer(&mut server_output, &mut client_input);

                println!(
                    "F: {} -> {:?}",
                    transferred,
                    client.read_tls(&mut client_input, &mut client_output)
                );
                assert_eq!(transferred, KEY_UPDATE_SIZE + encrypted_size(message.len()));
            }

