            #[test]
            fn client_data_sent() {
                for (client_config, server_config, _) in MultiTest::new(provider::DEFAULT_PROVIDER)
                {
                    let mut client_output = Vec::new();
                    let mut server_output = Vec::new();
                    let (mut client, mut server) = make_pair_for_arc_configs(
                        &client_config,
                        &server_config,
                        &mut client_output,
                    );
                    let mut client_input = VecInput::default();
                    let mut server_input = VecInput::default();

                    assert_eq!(
                        client
                            .write(b"hello".into(), &mut client_output)
                            .unwrap_err(),
                        ApiMisuse::WriteTlsBeforeHandshakeComplete.into()
                    );

                    let mut server_received = Vec::new();
                    do_handshake_collecting(
                        &mut client_input,
                        &mut client_output,
                        &mut client,
                        &mut Vec::new(),
                        &mut server_input,
                        &mut server_output,
                        &mut server,
                        &mut server_received,
                    );

                    client.write(b"hello".into(), &mut client_output).unwrap();
                    transfer(&mut client_output, &mut server_input);
                    server
                        .read_tls(&mut server_input, &mut server_output)
                        .handle_all(&mut server_received)
                        .unwrap();

                    assert_eq!(&server_received, b"hello");
                }
            }

