            #[test]
            fn test_complete_io_with_no_io_needed() {
                let mut client_output = Vec::new();
                let mut server_output = Vec::new();
                let (mut client, mut server) = make_pair(
                    KeyType::default(),
                    &provider::DEFAULT_PROVIDER,
                    &mut client_output,
                );
                let mut client_input = VecInput::default();
                let mut server_input = VecInput::default();
                let mut received_plaintext = Vec::new();

                do_handshake(
                    &mut client_input,
                    &mut client_output,
                    &mut client,
                    &mut server_input,
                    &mut server_output,
                    &mut server,
                );

                client.write(b"hello".into(), &mut client_output).unwrap();
                client.send_close_notify(&mut client_output);
                transfer(&mut client_output, &mut server_input);
                server
                    .read_tls(&mut server_input, &mut server_output)
                    .handle_all(&mut Vec::new())
                    .unwrap();
                server.write(b"hello".into(), &mut server_output).unwrap();
                server.send_close_notify(&mut server_output);
                transfer(&mut server_output, &mut client_input);
                client
                    .read_tls(&mut client_input, &mut client_output)
                    .handle_all(&mut Vec::new())
                    .unwrap();

                assert!(client_output.is_empty());
                assert!(!client.wants_read());
                assert!(server_output.is_empty());
                assert!(!server.wants_read());

                assert_eq!(
                    complete_io(
                        &mut FakeStream(&[]),
                        &mut client_input,
                        &mut received_plaintext,
                        &mut client_output,
                        &mut client
                    )
                    .unwrap(),
                    (0, 0)
                );

                assert_eq!(
                    complete_io(
                        &mut FakeStream(&[]),
                        &mut server_input,
                        &mut received_plaintext,
                        &mut server_output,
                        &mut server
                    )
                    .unwrap(),
                    (0, 0)
                );
            }

