            fn early_data_configs() -> (Arc<ClientConfig>, Arc<ServerConfig>) {
                let kt = KeyType::default();
                let provider = provider::DEFAULT_PROVIDER;
                let mut client_config = make_client_config(kt, &provider);
                client_config.enable_early_data = true;
                client_config.resumption = Resumption::store(Arc::new(ClientStorage::new()));

                let mut server_config = make_server_config(kt, &provider);
                server_config.max_early_data_size = 1234;
                (Arc::new(client_config), Arc::new(server_config))
            }

            #[test]
            fn early_data_is_available_on_resumption() {
                let (client_config, server_config) = early_data_configs();
                let mut client_input = VecInput::default();
                let mut server_input = VecInput::default();

                let mut client_output = Vec::new();
                let mut server_output = Vec::new();
                let (mut client, mut server) =
                    make_pair_for_arc_configs(&client_config, &server_config, &mut client_output);
                do_handshake(
                    &mut client_input,
                    &mut client_output,
                    &mut client,
                    &mut server_input,
                    &mut server_output,
                    &mut server,
                );

                let mut client_output = Vec::new();
                let mut server_output = Vec::new();
                let (mut client, mut server) =
                    make_pair_for_arc_configs(&client_config, &server_config, &mut client_output);
                assert!(client.early_data().is_some());
                assert_eq!(client.early_data().unwrap().bytes_left(), 1234);
                assert_eq!(
                    client
                        .early_data()
                        .unwrap()
                        .write(b"".into(), &mut client_output),
                    0
                );
                assert_eq!(
                    client
                        .early_data()
                        .unwrap()
                        .write(b"hello".into(), &mut client_output),
                    5
                );
                let client_early_exporter = client.early_data().unwrap().exporter().unwrap();
                assert_eq!(
                    client.early_data().unwrap().exporter().err(),
                    Some(Error::ApiMisuse(ApiMisuse::ExporterAlreadyUsed)),
                );
                do_handshake(
                    &mut client_input,
                    &mut client_output,
                    &mut client,
                    &mut server_input,
                    &mut server_output,
                    &mut server,
                );

                let mut received_early_data = [0u8; 5];
                assert_eq!(
                    server
                        .early_data()
                        .expect("early_data didn't happen")
                        .read(&mut received_early_data)
                        .expect("early_data failed unexpectedly"),
                    5
                );
                assert_eq!(&received_early_data[..], b"hello");
                let server_early_exporter = server.early_data().unwrap().exporter().unwrap();
                assert_eq!(
                    server.early_data().unwrap().exporter().err(),
                    Some(Error::ApiMisuse(ApiMisuse::ExporterAlreadyUsed)),
                );

                let client_secret = client_early_exporter
                    .derive(b"label", Some(b"context"), [0u8; 32])
                    .unwrap();
                let server_secret = server_early_exporter
                    .derive(b"label", Some(b"context"), [0u8; 32])
                    .unwrap();
                assert_eq!(client_secret, server_secret);
            }

