            #[test]
            fn server_detects_excess_streamed_early_data() {
                let (client_config, server_config) =
                    early_data_configs_allowing_client_to_send_excess_data();
                let mut server_input = VecInput::default();

                let mut client_output = Vec::new();
                let mut server_output = Vec::new();
                let (mut client, mut server) =
                    make_pair_for_arc_configs(&client_config, &server_config, &mut client_output);
                assert!(client.early_data().is_some());
                assert_eq!(client.early_data().unwrap().bytes_left(), 2024);
                assert_eq!(
                    client
                        .early_data()
                        .unwrap()
                        .write((&[0xaa; 1024]).into(), &mut client_output),
                    1024
                );
                transfer(&mut client_output, &mut server_input);
                server
                    .read_tls(&mut server_input, &mut server_output)
                    .handle_all(&mut Vec::new())
                    .unwrap();

                let mut received_early_data = [0u8; 1024];
                assert_eq!(
                    server
                        .early_data()
                        .expect("early_data didn't happen")
                        .read(&mut received_early_data)
                        .expect("early_data failed unexpectedly"),
                    1024
                );
                assert_eq!(&received_early_data[..], [0xaa; 1024]);

                assert_eq!(
                    client
                        .early_data()
                        .unwrap()
                        .write((&[0xbb; 1000]).into(), &mut client_output),
                    1000
                );
                transfer(&mut client_output, &mut server_input);
                assert_eq!(
                    server
                        .read_tls(&mut server_input, &mut server_output)
                        .handle_all(&mut Vec::new())
                        .unwrap_err(),
                    Error::PeerMisbehaved(PeerMisbehaved::TooMuchEarlyDataReceived)
                );
            }

            struct ServerStorage {
                storage: Arc<dyn crate::android_debug_bridge::rustls::server::StoresServerSessions>,
                put_count: AtomicUsize,
                get_count: AtomicUsize,
                take_count: AtomicUsize,
            }

            impl ServerStorage {
                fn new() -> Self {
                    Self {
            storage: crate::android_debug_bridge::rustls::server::ServerSessionMemoryCache::new(1024),
            put_count: AtomicUsize::new(0),
            get_count: AtomicUsize::new(0),
            take_count: AtomicUsize::new(0),
        }
                }

                fn puts(&self) -> usize {
                    self.put_count.load(Ordering::SeqCst)
                }
                fn gets(&self) -> usize {
                    self.get_count.load(Ordering::SeqCst)
                }
                fn takes(&self) -> usize {
                    self.take_count.load(Ordering::SeqCst)
                }
            }

            impl fmt::Debug for ServerStorage {
                fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
                    write!(
                        f,
                        "(put: {:?}, get: {:?}, take: {:?})",
                        self.put_count, self.get_count, self.take_count
                    )
                }
            }

            impl crate::android_debug_bridge::rustls::server::StoresServerSessions for ServerStorage {
                fn put(&self, key: ServerSessionKey<'_>, value: Vec<u8>) -> bool {
                    self.put_count.fetch_add(1, Ordering::SeqCst);
                    self.storage.put(key, value)
                }

                fn get(&self, key: ServerSessionKey<'_>) -> Option<Vec<u8>> {
                    self.get_count.fetch_add(1, Ordering::SeqCst);
                    self.storage.get(key)
                }

                fn take(&self, key: ServerSessionKey<'_>) -> Option<Vec<u8>> {
                    self.take_count.fetch_add(1, Ordering::SeqCst);
                    self.storage.take(key)
                }

                fn can_cache(&self) -> bool {
                    true
                }
            }

            #[test]
            fn tls13_ticket_request_new_vs_resumed() {
                let provider = provider::DEFAULT_TLS13_PROVIDER;
                let shared_storage = Arc::new(ClientStorage::new());

                let mut client_config = make_client_config(KeyType::default(), &provider);
                client_config.resumption = Resumption::store(shared_storage.clone());
                client_config.send_ticket_request = Some(TicketRequest {
                    new_session_count: 3,
                    resumption_count: 1,
                });
                let client_config = Arc::new(client_config);

                let mut server_config = make_server_config(KeyType::default(), &provider);

                server_config.send_tls13_tickets = Tls13Tickets { default: 2, max: 5 };
                let server_config = Arc::new(server_config);

                let mut client_output = Vec::new();
                let mut server_output = Vec::new();
                let (mut client, mut server) =
                    make_pair_for_arc_configs(&client_config, &server_config, &mut client_output);
                let mut client_input = VecInput::default();
                let mut server_input = VecInput::default();
                do_handshake(
                    &mut client_input,
                    &mut client_output,
                    &mut client,
                    &mut server_input,
                    &mut server_output,
                    &mut server,
                );
                assert_eq!(client.handshake_kind(), Some(HandshakeKind::Full));

                let ops = shared_storage.ops_and_reset();
                let ticket_inserts = ops
                    .iter()
                    .filter(|op| matches!(op, ClientStorageOp::InsertTls13Ticket(_)))
                    .count();
                assert_eq!(ticket_inserts, 3);

                let mut client_output = Vec::new();
                let mut server_output = Vec::new();
                let (mut client, mut server) =
                    make_pair_for_arc_configs(&client_config, &server_config, &mut client_output);
                let mut client_input = VecInput::default();
                let mut server_input = VecInput::default();
                do_handshake(
                    &mut client_input,
                    &mut client_output,
                    &mut client,
                    &mut server_input,
                    &mut server_output,
                    &mut server,
                );
                assert_eq!(client.handshake_kind(), Some(HandshakeKind::Resumed));

                let ops = shared_storage.ops_and_reset();
                let ticket_inserts = ops
                    .iter()
                    .filter(|op| matches!(op, ClientStorageOp::InsertTls13Ticket(_)))
                    .count();
                assert_eq!(ticket_inserts, 1);
            }

