            #[test]
            fn client_can_request_certain_trusted_cas() {
                let provider = provider::DEFAULT_PROVIDER;

                let key_types = [KeyType::Rsa2048, KeyType::Rsa3072, KeyType::Rsa4096];
                let cert_resolver = ResolvesCertChainByCaName(
                    key_types
                        .iter()
                        .map(|kt| {
                            (
                                kt.ca_distinguished_name(),
                                kt.credentials_with_cert_chain(&provider).unwrap(),
                            )
                        })
                        .collect(),
                );

                let server_config = Arc::new(
                    ServerConfig::builder(provider.clone().into())
                        .with_no_client_auth()
                        .with_server_credential_resolver(Arc::new(cert_resolver))
                        .unwrap(),
                );

                let mut cas_unaware_error_count = 0;

                for key_type in key_types {
                    let mut root_store = RootCertStore::empty();
                    root_store.add(key_type.ca_cert()).unwrap();
                    let server_verifier = Arc::new(
                        WebPkiServerVerifier::builder(Arc::new(root_store), &provider)
                            .build()
                            .unwrap(),
                    );

                    let cas_sending_server_verifier = Arc::new(ServerVerifierWithCasExt {
                        verifier: server_verifier.clone(),
                        ca_names: Arc::from(vec![key_type.ca_distinguished_name()]),
                    });

                    let cas_sending_client_config = ClientConfig::builder(provider.clone().into())
                        .dangerous()
                        .with_custom_certificate_verifier(cas_sending_server_verifier)
                        .with_no_client_auth()
                        .unwrap();

                    let mut client_output = Vec::new();
                    let mut server_output = Vec::new();
                    let (mut client, mut server) = make_pair_for_arc_configs(
                        &Arc::new(cas_sending_client_config),
                        &server_config,
                        &mut client_output,
                    );
                    let mut client_input = VecInput::default();
                    let mut server_input = VecInput::default();
                    do_handshake(
                        &mut client_input,
                        &mut client_output,
                        &mut client,
                        &mut server_input,
                        &mut server_output,
                        &mut server,
                    );

                    let cas_unaware_client_config = ClientConfig::builder(provider.clone().into())
                        .dangerous()
                        .with_custom_certificate_verifier(server_verifier)
                        .with_no_client_auth()
                        .unwrap();

                    let mut client_output = Vec::new();
                    let mut server_output = Vec::new();
                    let (mut client, mut server) = make_pair_for_arc_configs(
                        &Arc::new(cas_unaware_client_config),
                        &server_config,
                        &mut client_output,
                    );
                    let mut client_input = VecInput::default();
                    let mut server_input = VecInput::default();

                    cas_unaware_error_count += do_handshake_until_error(
                        &mut client_input,
                        &mut client_output,
                        &mut client,
                        &mut server_input,
                        &mut server_output,
                        &mut server,
                    )
                    .inspect_err(|e| {
                        assert!(matches!(
                            e,
                            ErrorFromPeer::Client(Error::InvalidCertificate(
                                CertificateError::UnknownIssuer
                            ))
                        ))
                    })
                    .is_err() as usize;

                    println!("key type {key_type:?} success!");
                }

                assert_eq!(cas_unaware_error_count, key_types.len() - 1);
            }

            #[test]
            fn client_checks_server_certificate_with_given_ip_address() {
                fn check_server_name(
                    client_config: Arc<ClientConfig>,
                    server_config: Arc<ServerConfig>,
                    name: &'static str,
                ) -> Result<(), ErrorFromPeer> {
                    let mut client_output = Vec::new();
                    let mut server_output = Vec::new();
                    let mut client = client_config
                        .connect(server_name(name))
                        .build(&mut client_output)
                        .unwrap();
                    let mut server = ServerConnection::new(server_config).unwrap();
                    let mut client_input = VecInput::default();
                    let mut server_input = VecInput::default();
                    do_handshake_until_error(
                        &mut client_input,
                        &mut client_output,
                        &mut client,
                        &mut server_input,
                        &mut server_output,
                        &mut server,
                    )
                }

                for (client_config, server_config, _) in MultiTest::new(provider::DEFAULT_PROVIDER)
                {
                    assert_eq!(
                        check_server_name(
                            client_config.clone(),
                            server_config.clone(),
                            "198.51.100.1"
                        ),
                        Ok(()),
                    );

                    assert_eq!(
                        check_server_name(
                            client_config.clone(),
                            server_config.clone(),
                            "198.51.100.2"
                        ),
                        Err(ErrorFromPeer::Client(Error::InvalidCertificate(
                            certificate_error_expecting_name("198.51.100.2")
                        )))
                    );

                    assert_eq!(
                        check_server_name(
                            client_config.clone(),
                            server_config.clone(),
                            "2001:db8::1"
                        ),
                        Ok(()),
                    );

                    assert_eq!(
                        check_server_name(client_config, server_config, "2001:db8::2"),
                        Err(ErrorFromPeer::Client(Error::InvalidCertificate(
                            certificate_error_expecting_name("2001:db8::2")
                        )))
                    );
                }
            }

