            fn unoffered_alpn_test(
                check_selected_alpn: bool,
            ) -> Result<crate::android_debug_bridge::rustls::IoState, Error> {
                let mut config =
                    make_client_config(KeyType::default(), &provider::DEFAULT_PROVIDER);
                config.check_selected_alpn = check_selected_alpn;
                let mut client_output = Vec::new();
                let mut client = Arc::new(config)
                    .connect(server_name("localhost"))
                    .with_alpn(vec![ApplicationProtocol::Http11])
                    .build(&mut client_output)
                    .unwrap();
                client_output.clear();

                let mut input = VecInput::default();
                input
                    .read(
                        &mut encoding::record_framing(
                            ContentType::Handshake,
                            ProtocolVersion::TLSv1_2,
                            encoding::server_hello(
                                ProtocolVersion::TLSv1_2,
                                &[b'a'; 32],
                                &[0],
                                CipherSuite::TLS_ECDHE_ECDSA_WITH_AES_128_GCM_SHA256,
                                vec![encoding::Extension::new_alpn(b"\x05blorp")],
                            ),
                        )
                        .as_slice(),
                    )
                    .unwrap();

                let state = client
                    .read_tls(&mut input, &mut client_output)
                    .handle_all(&mut Vec::new())?;
                Ok(state)
            }

            fn version_test(
                client_versions: &[ProtocolVersion],
                server_versions: &[ProtocolVersion],
                result: Option<ProtocolVersion>,
            ) {
                let provider = provider::DEFAULT_PROVIDER;
                let client_provider = apply_versions(provider.clone(), client_versions);
                let server_provider = apply_versions(provider, server_versions);

                let client_config = make_client_config(KeyType::default(), &client_provider);
                let server_config = make_server_config(KeyType::default(), &server_provider);

                println!("version {client_versions:?} {server_versions:?} -> {result:?}");

                let mut client_output = Vec::new();
                let mut server_output = Vec::new();
                let (mut client, mut server) =
                    make_pair_for_configs(client_config, server_config, &mut client_output);
                let mut client_input = VecInput::default();
                let mut server_input = VecInput::default();

                assert_eq!(client.protocol_version(), None);
                assert_eq!(server.protocol_version(), None);
                if result.is_none() {
                    let err = do_handshake_until_error(
                        &mut client_input,
                        &mut client_output,
                        &mut client,
                        &mut server_input,
                        &mut server_output,
                        &mut server,
                    );
                    assert!(err.is_err());
                } else {
                    do_handshake(
                        &mut client_input,
                        &mut client_output,
                        &mut client,
                        &mut server_input,
                        &mut server_output,
                        &mut server,
                    );
                    assert_eq!(client.protocol_version(), result);
                    assert_eq!(server.protocol_version(), result);
                }
            }

            fn apply_versions(
                provider: CryptoProvider,
                versions: &[ProtocolVersion],
            ) -> CryptoProvider {
                match versions {
                    []
                    | [ProtocolVersion::TLSv1_3, ProtocolVersion::TLSv1_2]
                    | [ProtocolVersion::TLSv1_2, ProtocolVersion::TLSv1_3] => provider,
                    [ProtocolVersion::TLSv1_3] => CryptoProvider {
                        tls12_cipher_suites: Cow::Borrowed(&[]),
                        ..provider
                    },
                    [ProtocolVersion::TLSv1_2] => CryptoProvider {
                        tls13_cipher_suites: Cow::Borrowed(&[]),
                        ..provider
                    },
                    _ => panic!("unhandled versions {versions:?}"),
                }
            }

            #[test]
            fn versions() {
                version_test(&[], &[], Some(ProtocolVersion::TLSv1_3));

                version_test(
                    &[],
                    &[ProtocolVersion::TLSv1_2],
                    Some(ProtocolVersion::TLSv1_2),
                );

                version_test(
                    &[ProtocolVersion::TLSv1_2],
                    &[],
                    Some(ProtocolVersion::TLSv1_2),
                );

                version_test(
                    &[ProtocolVersion::TLSv1_2],
                    &[ProtocolVersion::TLSv1_3],
                    None,
                );

                version_test(
                    &[ProtocolVersion::TLSv1_3],
                    &[ProtocolVersion::TLSv1_2],
                    None,
                );

                version_test(
                    &[ProtocolVersion::TLSv1_3],
                    &[ProtocolVersion::TLSv1_2, ProtocolVersion::TLSv1_3],
                    Some(ProtocolVersion::TLSv1_3),
                );

                version_test(
                    &[ProtocolVersion::TLSv1_3, ProtocolVersion::TLSv1_2],
                    &[ProtocolVersion::TLSv1_2],
                    Some(ProtocolVersion::TLSv1_2),
                );
            }

            #[test]
            fn server_does_not_negotiate_tls12_after_hrr() {
                let (_, mut server) = make_pair(
                    KeyType::Rsa2048,
                    &provider::DEFAULT_PROVIDER,
                    &mut Vec::new(),
                );

                let mut server_output = Vec::new();
                let mut input = encoding::record_framing(
                    ContentType::Handshake,
                    ProtocolVersion::TLSv1_2,
                    encoding::client_hello_with_extensions(vec![
                        encoding::Extension::new_sig_algs(),
                        encoding::Extension::new_kx_groups(),
                        encoding::Extension::new_versions(),
                        encoding::Extension {
                            typ: encoding::Extension::KEY_SHARE,
                            body: vec![0, 0],
                        },
                    ]),
                );
                server
                    .read_tls(&mut SliceInput::new(&mut input), &mut server_output)
                    .handle_all(&mut Vec::new())
                    .unwrap();

                assert!(
                    &server_output[11..43] == HRR_RANDOM_VALUE,
                    "server didn't reply with a HRR"
                );
                server_output.clear();

                let mut input = encoding::record_framing(
                    ContentType::Handshake,
                    ProtocolVersion::TLSv1_2,
                    encoding::client_hello_with_extensions(vec![
                        encoding::Extension::new_sig_algs(),
                        encoding::Extension::new_kx_groups(),
                    ]),
                );
                assert_eq!(
                    server
                        .read_tls(&mut SliceInput::new(&mut input), &mut server_output)
                        .handle_all(&mut Vec::new())
                        .unwrap_err(),
                    PeerIncompatible::SupportedVersionsExtensionRequired.into()
                );
            }

            const HRR_RANDOM_VALUE: &[u8] = &[
                0xcf, 0x21, 0xad, 0x74, 0xe5, 0x9a, 0x61, 0x11, 0xbe, 0x1d, 0x8c, 0x02, 0x1e, 0x65,
                0xb8, 0x91, 0xc2, 0xa2, 0x11, 0x16, 0x7a, 0xbb, 0x8c, 0x5e, 0x07, 0x9e, 0x09, 0xe2,
                0xc8, 0xa8, 0x33, 0x9c,
            ];

