            #[test]
            fn client_can_get_server_cert_after_resumption() {
                for (client_config, server_config, _) in MultiTest::new(provider::DEFAULT_PROVIDER)
                {
                    let mut client_output = Vec::new();
                    let mut server_output = Vec::new();
                    let (mut client, mut server) = make_pair_for_arc_configs(
                        &client_config,
                        &server_config,
                        &mut client_output,
                    );
                    let mut client_input = VecInput::default();
                    let mut server_input = VecInput::default();
                    do_handshake(
                        &mut client_input,
                        &mut client_output,
                        &mut client,
                        &mut server_input,
                        &mut server_output,
                        &mut server,
                    );
                    assert_eq!(client.handshake_kind(), Some(HandshakeKind::Full));

                    let original_certs = client.peer_identity();

                    let mut client_output = Vec::new();
                    let mut server_output = Vec::new();
                    let (mut client, mut server) = make_pair_for_arc_configs(
                        &client_config,
                        &server_config,
                        &mut client_output,
                    );
                    let mut client_input = VecInput::default();
                    let mut server_input = VecInput::default();
                    do_handshake(
                        &mut client_input,
                        &mut client_output,
                        &mut client,
                        &mut server_input,
                        &mut server_output,
                        &mut server,
                    );
                    assert_eq!(client.handshake_kind(), Some(HandshakeKind::Resumed));

                    let resumed_certs = client.peer_identity();

                    assert_eq!(original_certs, resumed_certs);
                }
            }

