            #[test]
            fn test_tls13_exporter_maximum_output_length() {
                let provider = provider::DEFAULT_TLS13_PROVIDER;
                let client_config = make_client_config(KeyType::default(), &provider);
                let server_config = make_server_config(KeyType::default(), &provider);

                let mut client_output = Vec::new();
                let mut server_output = Vec::new();
                let (mut client, mut server) =
                    make_pair_for_configs(client_config, server_config, &mut client_output);
                let mut client_input = VecInput::default();
                let mut server_input = VecInput::default();
                do_handshake(
                    &mut client_input,
                    &mut client_output,
                    &mut client,
                    &mut server_input,
                    &mut server_output,
                    &mut server,
                );

                assert_eq!(
                    client.negotiated_cipher_suite(),
                    Some(find_suite(CipherSuite::TLS13_AES_128_GCM_SHA256))
                );

                let client_exporter = client.exporter().unwrap();
                let server_exporter = server.exporter().unwrap();

                let mut maximum_allowed_output_client = [0u8; 255 * 32];
                let mut maximum_allowed_output_server = [0u8; 255 * 32];

                client_exporter
                    .derive(
                        b"label",
                        Some(b"context"),
                        &mut maximum_allowed_output_client,
                    )
                    .unwrap();
                server_exporter
                    .derive(
                        b"label",
                        Some(b"context"),
                        &mut maximum_allowed_output_server,
                    )
                    .unwrap();

                assert_eq!(maximum_allowed_output_client, maximum_allowed_output_server);

                let mut too_long_output = [0u8; 255 * 48 + 1];
                assert_eq!(
                    client_exporter
                        .derive(b"label", Some(b"context"), &mut too_long_output)
                        .err(),
                    Some(ApiMisuse::ExporterOutputTooLong.into())
                );
                assert_eq!(
                    server_exporter
                        .derive(b"label", Some(b"context"), &mut too_long_output)
                        .err(),
                    Some(ApiMisuse::ExporterOutputTooLong.into())
                );
            }

            fn find_suite(suite: CipherSuite) -> SupportedCipherSuite {
                if let Some(found) = provider::ALL_TLS12_CIPHER_SUITES
                    .iter()
                    .find(|cs| cs.common.suite == suite)
                {
                    return SupportedCipherSuite::Tls12(found);
                }

                if let Some(found) = provider::ALL_TLS13_CIPHER_SUITES
                    .iter()
                    .find(|cs| cs.common.suite == suite)
                {
                    return SupportedCipherSuite::Tls13(found);
                }

                panic!("find_suite given unsupported suite {suite:?}");
            }

            fn test_ciphersuites() -> Vec<(ProtocolVersion, KeyType, CipherSuite)> {
                let mut v = vec![
                    (
                        ProtocolVersion::TLSv1_3,
                        KeyType::Rsa2048,
                        CipherSuite::TLS13_AES_256_GCM_SHA384,
                    ),
                    (
                        ProtocolVersion::TLSv1_3,
                        KeyType::Rsa2048,
                        CipherSuite::TLS13_AES_128_GCM_SHA256,
                    ),
                    (
                        ProtocolVersion::TLSv1_2,
                        KeyType::EcdsaP384,
                        CipherSuite::TLS_ECDHE_ECDSA_WITH_AES_256_GCM_SHA384,
                    ),
                    (
                        ProtocolVersion::TLSv1_2,
                        KeyType::EcdsaP384,
                        CipherSuite::TLS_ECDHE_ECDSA_WITH_AES_128_GCM_SHA256,
                    ),
                    (
                        ProtocolVersion::TLSv1_2,
                        KeyType::Rsa2048,
                        CipherSuite::TLS_ECDHE_RSA_WITH_AES_256_GCM_SHA384,
                    ),
                    (
                        ProtocolVersion::TLSv1_2,
                        KeyType::Rsa2048,
                        CipherSuite::TLS_ECDHE_RSA_WITH_AES_128_GCM_SHA256,
                    ),
                ];

                if !provider_is_fips() {
                    v.extend_from_slice(&[
                        (
                            ProtocolVersion::TLSv1_3,
                            KeyType::Rsa2048,
                            CipherSuite::TLS13_CHACHA20_POLY1305_SHA256,
                        ),
                        (
                            ProtocolVersion::TLSv1_2,
                            KeyType::EcdsaP256,
                            CipherSuite::TLS_ECDHE_ECDSA_WITH_CHACHA20_POLY1305_SHA256,
                        ),
                        (
                            ProtocolVersion::TLSv1_2,
                            KeyType::Rsa2048,
                            CipherSuite::TLS_ECDHE_RSA_WITH_CHACHA20_POLY1305_SHA256,
                        ),
                    ]);
                }

                v
            }

