    #[test]
    fn doc_conn_kernel_line_146() {
        #[allow(unreachable_code, unused, clippy::all)]
        fn doc_body() {
            use crate::android_debug_bridge::rustls::client::ClientSide;
            use crate::android_debug_bridge::rustls::enums::{ContentType, HandshakeType};
            use crate::android_debug_bridge::rustls::kernel::KernelConnection;

            fn doctest(
                conn: &mut KernelConnection<ClientSide>,
                typ: ContentType,
                message: &[u8],
            ) -> Result<(), crate::android_debug_bridge::rustls::Error> {
                let conn: &mut KernelConnection<ClientSide> = conn;
                let typ: ContentType = typ;
                let mut message: &[u8] = message;

                assert_eq!(typ, ContentType::Handshake);

                while !message.is_empty() {
                    let (typ, len, rest) = match message {
                        &[typ, a, b, c, ref rest @ ..] => (
                            HandshakeType::from(typ),
                            u32::from_be_bytes([0, a, b, c]) as usize,
                            rest,
                        ),
                        _ => panic!("error handling not included in this example"),
                    };

                    assert_eq!(typ, HandshakeType::NewSessionTicket);
                    assert!(rest.len() >= len, "invalid handshake message");

                    let (payload, rest) = rest.split_at(len);
                    message = rest;

                    conn.handle_new_session_ticket(payload)?;
                }
                Ok(())
            }
        }
        let _ = doc_body as fn();
    }

