#[allow(clippy::crate_in_macro_def)]
#[macro_export]
macro_rules! adb_t034 {
    ($d:tt) => {
        mod tests {

            use std::format;
            use std::vec;

            use super::*;
            use crate::android_debug_bridge::rustls::crypto::{SignatureScheme, TEST_PROVIDER};
            use crate::android_debug_bridge::rustls::verify::DigitallySignedStruct;

            #[test]
            fn tls13_empty_signature_mapping_panics() {
                let supported = WebPkiSupportedAlgorithms {
                    all: TEST_PROVIDER.signature_verification_algorithms.all,
                    mapping: &[(SignatureScheme::ED25519, &[])],
                };

                let cert = CertificateDer::from(vec![0u8]);
                let dss = DigitallySignedStruct::new(SignatureScheme::ED25519, vec![]);
                let signer = SignerPublicKey::X509(&cert);
                let input = SignatureVerificationInput {
                    message: b"hello",
                    signer: &signer,
                    signature: &dss,
                };

                assert_eq!(
                    verify_tls13_signature(&input, &supported).unwrap_err(),
                    Error::ApiMisuse(ApiMisuse::NoSignatureVerificationAlgorithms)
                );
            }

            #[test]
            fn certificate_debug() {
                assert_eq!(
                    "CertificateDer(0x6162)",
                    format!("{:?}", CertificateDer::from(b"ab".to_vec()))
                );
            }

            #[test]
            fn webpki_supported_algorithms_is_debug() {
                assert_eq!(
                    "WebPkiSupportedAlgorithms { all: [ .. ], mapping: [] }",
                    format!(
                        "{:?}",
                        WebPkiSupportedAlgorithms {
                            all: &[],
                            mapping: &[]
                        }
                    )
                );
            }
        }
    };
}

#[allow(clippy::crate_in_macro_def)]
#[macro_export]
macro_rules! adb_t035 {
($d:tt) => {
  mod tests {

    use std::vec;

    use super::*;

    #[test]
    fn pki_crl_errors() {

        assert_eq!(
            pki_error(crate::android_debug_bridge::webpki::Error::InvalidCrlSignatureForPublicKey),
            Error::InvalidCertRevocationList(CertRevocationListError::BadSignature),
        );

        assert_eq!(
            pki_error(crate::android_debug_bridge::webpki::Error::UnsupportedCrlSignatureAlgorithm(
                crate::android_debug_bridge::webpki::UnsupportedSignatureAlgorithmContext {
                    signature_algorithm_id: vec![],
                    supported_algorithms: vec![],
                }
            )),
            Error::InvalidCertRevocationList(
                CertRevocationListError::UnsupportedSignatureAlgorithm {
                    signature_algorithm_id: vec![],
                    supported_algorithms: vec![],
                }
            )
        );
        assert_eq!(
            pki_error(crate::android_debug_bridge::webpki::Error::UnsupportedCrlSignatureAlgorithmForPublicKey(
                crate::android_debug_bridge::webpki::UnsupportedSignatureAlgorithmForPublicKeyContext {
                    signature_algorithm_id: vec![],
                    public_key_algorithm_id: vec![],
                }
            )),
            Error::InvalidCertRevocationList(
                CertRevocationListError::UnsupportedSignatureAlgorithmForPublicKey {
                    signature_algorithm_id: vec![],
                    public_key_algorithm_id: vec![],
                }
            )
        );

        assert_eq!(
            pki_error(crate::android_debug_bridge::webpki::Error::CertRevoked),
            Error::InvalidCertificate(CertificateError::Revoked),
        );

        assert_eq!(
            pki_error(crate::android_debug_bridge::webpki::Error::IssuerNotCrlSigner),
            Error::InvalidCertRevocationList(CertRevocationListError::IssuerInvalidForCrl)
        );
    }

    #[test]
    fn crl_error_from_webpki() {
        use CertRevocationListError::*;
        let testcases = &[
            (crate::android_debug_bridge::webpki::Error::InvalidCrlSignatureForPublicKey, BadSignature),
            (
                crate::android_debug_bridge::webpki::Error::UnsupportedCrlSignatureAlgorithm(
                    crate::android_debug_bridge::webpki::UnsupportedSignatureAlgorithmContext {
                        signature_algorithm_id: vec![],
                        supported_algorithms: vec![],
                    },
                ),
                UnsupportedSignatureAlgorithm {
                    signature_algorithm_id: vec![],
                    supported_algorithms: vec![],
                },
            ),
            (
                crate::android_debug_bridge::webpki::Error::UnsupportedCrlSignatureAlgorithmForPublicKey(
                    crate::android_debug_bridge::webpki::UnsupportedSignatureAlgorithmForPublicKeyContext {
                        signature_algorithm_id: vec![],
                        public_key_algorithm_id: vec![],
                    },
                ),
                UnsupportedSignatureAlgorithmForPublicKey {
                    signature_algorithm_id: vec![],
                    public_key_algorithm_id: vec![],
                },
            ),
            (crate::android_debug_bridge::webpki::Error::InvalidCrlNumber, InvalidCrlNumber),
            (
                crate::android_debug_bridge::webpki::Error::InvalidSerialNumber,
                InvalidRevokedCertSerialNumber,
            ),
            (crate::android_debug_bridge::webpki::Error::IssuerNotCrlSigner, IssuerInvalidForCrl),
            (crate::android_debug_bridge::webpki::Error::MalformedExtensions, ParseError),
            (crate::android_debug_bridge::webpki::Error::BadDer, ParseError),
            (crate::android_debug_bridge::webpki::Error::BadDerTime, ParseError),
            (
                crate::android_debug_bridge::webpki::Error::UnsupportedCriticalExtension,
                UnsupportedCriticalExtension,
            ),
            (crate::android_debug_bridge::webpki::Error::UnsupportedCrlVersion, UnsupportedCrlVersion),
            (crate::android_debug_bridge::webpki::Error::UnsupportedDeltaCrl, UnsupportedDeltaCrl),
            (
                crate::android_debug_bridge::webpki::Error::UnsupportedIndirectCrl,
                UnsupportedIndirectCrl,
            ),
            (
                crate::android_debug_bridge::webpki::Error::UnsupportedRevocationReason,
                UnsupportedRevocationReason,
            ),
        ];
        for t in testcases {
            std::println!("webpki: {:?}", t.0);
            std::println!("rustls: {:?}", t.1);
            assert_eq!(crl_error(t.0.clone()), t.1);
        }

        assert!(matches!(
            crl_error(crate::android_debug_bridge::webpki::Error::NameConstraintViolation),
            Other(..)
        ));
    }

}
};
}

#[allow(clippy::crate_in_macro_def)]
#[macro_export]
macro_rules! adb_t036 {
($d:tt) => {
  mod tests {

    use core::sync::atomic::{AtomicU8, Ordering};
    use core::time::Duration;
    use std::string::String;

    use crate::android_debug_bridge::pki_types::{CertificateDer, SubjectPublicKeyInfoDer, UnixTime};

    use super::*;
    use crate::android_debug_bridge::rustls::client::{
        ClientSessionKey, ClientSessionMemoryCache, ClientSessionStore, Resumption,
        Tls13ClientSessionInput, VerifiedIdentity,
    };
    use crate::android_debug_bridge::rustls::conn::Connection;
    use crate::android_debug_bridge::rustls::crypto::cipher::Record;
    use crate::android_debug_bridge::rustls::crypto::hpke::{HpkeAead, HpkeKdf};
    use crate::android_debug_bridge::rustls::crypto::{CipherSuite, GetRandomFailed, Identity, TEST_PROVIDER, tls13_only};
    use crate::android_debug_bridge::rustls::msgs::{
        Compression, HelloRetryRequestExtensions, NewSessionTicketPayloadTls13, Random, Reader,
        ServerExtensions, SessionId,
    };
    use crate::android_debug_bridge::rustls::sync::Arc;
    use crate::android_debug_bridge::rustls::tls13::Tls13ProtocolSuite;
    use crate::android_debug_bridge::rustls::{RootCertStore, VecInput};

    #[test]
    fn server_hello_conf_alters_server_hello_random() {
        let server_hello = ServerHelloPayload {
            legacy_version: ProtocolVersion::TLSv1_2,
            random: Random([0xffu8; 32]),
            session_id: SessionId::empty(),
            cipher_suite: CipherSuite::TLS13_AES_256_GCM_SHA384,
            compression_method: Compression::Null,
            extensions: Box::new(ServerExtensions::default()),
        };
        let message = Message {
            version: EncodableVersion::Legacy(ProtocolVersion::TLSv1_3),
            payload: MessagePayload::handshake(HandshakeMessagePayload(
                HandshakePayload::ServerHello(server_hello.clone()),
            )),
        };
        let Message {
            payload:
                MessagePayload::Handshake {
                    encoded: server_hello_encoded_before,
                    ..
                },
            ..
        } = &message
        else {
            unreachable!("ServerHello is a handshake message");
        };

        let message = EchState::server_hello_conf(&server_hello, server_hello_encoded_before);

        let Message {
            payload:
                MessagePayload::Handshake {
                    encoded: server_hello_encoded_after,
                    ..
                },
            ..
        } = &message
        else {
            unreachable!("ServerHello is a handshake message");
        };

        assert_eq!(
            std::format!("{server_hello_encoded_before:x?}"),
            "020000280303ffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff001302000000",
            "beforehand eight bytes at end of Random should be 0xff here ^^^^^^^^^^^^^^^^            "
        );
        assert_eq!(
            std::format!("{server_hello_encoded_after:x?}"),
            "020000280303ffffffffffffffffffffffffffffffffffffffffffffffff0000000000000000001302000000",
            "                          afterwards those bytes are zeroed ^^^^^^^^^^^^^^^^            "
        );
    }

    #[test]
    fn inner_client_hello_length_conceals_inner_name_length() {
        let base_inner_len = inner_hello_encoding_for_name(dns_name_of_len(1), true)
            .unwrap()
            .len();
        assert!(
            base_inner_len % 32 == 0,
            "inner hello length must be 32-byte padded"
        );
        assert!(
            base_inner_len >= 256,
            "inner hello must include inner name and its padding"
        );

        for inner_name_len in 1..251 {
            assert_eq!(
                inner_hello_encoding_for_name(dns_name_of_len(inner_name_len), true)
                    .unwrap()
                    .len(),
                base_inner_len,
                "all inner hello lengths must be invariant wrt inner name length"
            );
        }
    }

    #[test]
    fn inner_client_hello_length_does_not_leak_length_of_omitted_inner_name() {
        let base_inner_len = inner_hello_encoding_for_name(dns_name_of_len(1), false)
            .unwrap()
            .len();
        assert!(
            base_inner_len % 32 == 0,
            "inner hello length must be 32-byte padded"
        );
        assert!(
            base_inner_len >= 256,
            "inner hello must include maximum_name_length bytes of padding"
        );

        for inner_name_len in 1..251 {
            assert_eq!(
                inner_hello_encoding_for_name(dns_name_of_len(inner_name_len), false)
                    .unwrap()
                    .len(),
                base_inner_len,
                "all inner hello lengths must be invariant wrt inner name length"
            );
        }
    }

    #[test]
    fn ech_rejected_by_hello_retry_request_conceals_inner_psk() {
        let mut roots = RootCertStore::empty();
        roots
            .add(CertificateDer::from_slice(b"0\x82\x03?0\x82\x02'\xa0\x03\x02\x01\x02\x02\x01\x010\x0d\x06\x09*\x86H\x86\xf7\x0d\x01\x01\x0b\x05\x000\x1f1\x1d0\x1b\x06\x03U\x04\x03\x0c\x14ponytown RSA 2048 CA0 \x17\x0d750101000000Z\x18\x0f40960101000000Z0\x1f1\x1d0\x1b\x06\x03U\x04\x03\x0c\x14ponytown RSA 2048 CA0\x82\x01\x220\x0d\x06\x09*\x86H\x86\xf7\x0d\x01\x01\x01\x05\x00\x03\x82\x01\x0f\x000\x82\x01\x0a\x02\x82\x01\x01\x00\xb2\xe1\x93\xf3\xad\x0c\x1f\xbb{s\xdeYt\xc4|\xe5\x1e\xd0\x10\x10u2_4\xa8\xddR'P\xb1O\x0b\xd0\xfc\xe0\xb5\x9e\xf7:P\x05\x81\xb1:\xd9|9W\x0cva\x1b\xce\x82\x0e\x1c\xee\x9a|\xd4\xa7\xcd\xb7\x10u\x9c\xa6'\x8f\x852\x99\xae\xb1gU\x09\xc5\x90\xec\xa9\xee\xe0\xe94\x99ip\xecu\xe0\xb6xn\x9e5\xf4\x05\x132\xe4\xce\x96]i:0~8\x1b\xb9\xf7\x0c$\x03 \xd0\x09\xbc`0\x8a\xb2\x13\x91G\xde\x91\xb9\xf0\x0c\x22\x04\x98\x86MA\x02\xb2\x19\xd9\xdd\x9f\xa9\x90\x18{~\xa1gf\x82%\xb1#GO\x8dO\xef\xb3!P\x0cZ&_b\x05\xfd\xf9\xf8\x8f\xf9J\xbe\x11\x8f\x11\xc7\x0e\xffl\xd0N\x15+mW$\xd6\xde\xe4F)B\x0d\x96\xd2\x84f\xaf\xdf\xef;\x87\x8d\xa6!*\xe2+\x9c\xaaT\xec\x0f\xcc\xf2\xf8\x1dh\xc8/\xe1\xb6\xb0\xc0\xd8\xed\x17E)\x01\xc1\x09\x8e\x06\x8a\xcek\xac\xbbN:\x12\xad\xa09\xa8\xb3\xba\x02\x0a\xcdA\x02\x03\x01\x00\x01\xa3\x81\x830\x81\x800\x1f\x06\x03U\x1d#\x04\x180\x16\x80\x14g\xc7\xca\x9e\xbe\xbdm\x9a\xef8\xe45&(\xba\xd2\xf1\xbd\x10\xb60\x0e\x06\x03U\x1d\x0f\x01\x01\xff\x04\x04\x03\x02\x01\xfe0\x1d\x06\x03U\x1d%\x04\x160\x14\x06\x08+\x06\x01\x05\x05\x07\x03\x01\x06\x08+\x06\x01\x05\x05\x07\x03\x020\x1d\x06\x03U\x1d\x0e\x04\x16\x04\x14g\xc7\xca\x9e\xbe\xbdm\x9a\xef8\xe45&(\xba\xd2\xf1\xbd\x10\xb60\x0f\x06\x03U\x1d\x13\x01\x01\xff\x04\x050\x03\x01\x01\xff0\x0d\x06\x09*\x86H\x86\xf7\x0d\x01\x01\x0b\x05\x00\x03\x82\x01\x01\x00\x855;\x22\xff\xc7\x06\xe4\x8eh\x80\x0eN\xb8*n\xfc\x0aR\x86l\x18m/oP\xd59\x82\x0dj\xc9\xc3\x0d\x5c~q\xe9T\xf6;\xf3Htr\xfb\x99\x19R\x07\xe5\xca\xd6H\xcbT\xe6\x13\xf4oB/?\xbd\xdd\xac\xe8\x12\xf8\x0caw\xf5\x5c\x85;\x8f`\xef\x8e\x84p\x15\x04\x98\xd1\x99\x15-\x09\xfe\x15Z\x89\x98\xf7\xc8\xd3\xbf\xb4\xeeU\xde|\xeb\x1b4\xeb\xaf\x1f\x5cFqr\x90\xb2\x84\xfe\xa0\xe7\xac\x83\x9f\x0a$d\xe4\xa6.\x8bS9%\x80L\xebZ\xf702\xc0\x96\xb4Bf\x1e.\xd3\x88\xdd5Q\xcf\x17^$\x9b\x95\x5c\x80\x9b\xe1\xa4i\x17\xdaj^\xdc\x9fY\xb4\xec\x01u\xcfz{\x9c\xc9\xd0\xf3\xca\xa1\xf0.V\x1b\x83'\xcb~@\xd9\xe3\x5c\xa4\xb2\x7fU\x1d\xff\x95\x808\xa8\xa7\xa8b\xbd\xd3i\x91\x03\x01\x05!$$\xa3C\x9a\x8dI\x14\xce6Zn\xbe\xb1\x9d\xfe\x1fab\x1d$\xf4\xfd\xb2-\x04\xe8<QR`SC@\xf2\xe355\x01"))
            .unwrap();

        let mut provider = tls13_only(TEST_PROVIDER.clone());
        provider.secure_random = &CountingRandom;

        let config = ClientConfig::builder(Arc::new(provider))
            .with_ech(EchMode::Enable(EchConfig {
                config: EchConfigPayload::V18(EchConfigContents {
                    key_config: HpkeKeyConfig {
                        config_id: 0,
                        kem_id: MockHpke::SUITE.kem,
                        public_key: vec![0; 32].into(),
                        symmetric_cipher_suites: vec![MockHpke::SUITE.sym],
                    },
                    maximum_name_length: 255,
                    public_name: DnsName::try_from("public.example.com").unwrap(),
                    extensions: vec![],
                }),
                suite: &MockHpke,
            }))
            .with_root_certificates(roots)
            .with_no_client_auth()
            .unwrap();
        let store = Arc::new(ClientSessionMemoryCache::new(256));
        let config = Arc::new(ClientConfig {
            resumption: Resumption::store(store.clone()),
            ..config
        });

        let server_name = ServerName::try_from("inner.example.com").unwrap();
        store.insert_tls13_ticket(
            ClientSessionKey {
                config_hash: config.config_hash(),
                server_name: server_name.clone(),
            },
            Tls13Session::new(
                &NewSessionTicketPayloadTls13::new(
                    Duration::from_secs(1800),
                    0x1234_5678,
                    [0u8; 32],
                    TICKET.to_vec(),
                ),
                Tls13ClientSessionInput {
                    suite: Tls13ProtocolSuite::Tcp(TEST_PROVIDER.tls13_cipher_suites[0]),
                    peer_identity: VerifiedIdentity::assertion(Identity::RawPublicKey(
                        SubjectPublicKeyInfoDer::from(&b"spki"[..]),
                    )),
                    quic_params: None,
                },
                &[0x55; 32],
                UnixTime::now(),
            ),
        );

        let mut first_flight = Vec::new();
        let mut conn = config
            .connect(server_name)
            .build(&mut first_flight)
            .unwrap();

        let first = client_hello_in(&first_flight);
        assert_ne!(psk_identity(&first), TICKET);

        let hrr = Message {
            version: EncodableVersion::Legacy(ProtocolVersion::TLSv1_2),
            payload: MessagePayload::handshake(HandshakeMessagePayload(
                HandshakePayload::HelloRetryRequest(HelloRetryRequest {
                    legacy_version: ProtocolVersion::TLSv1_2,
                    session_id: first.session_id,
                    cipher_suite: first.cipher_suites[0],
                    extensions: HelloRetryRequestExtensions {
                        cookie: Some(SizedPayload::from(vec![1, 2, 3, 4])),
                        supported_versions: Some(ProtocolVersion::TLSv1_3),
                        ..HelloRetryRequestExtensions::default()
                    },
                }),
            )),
        };
        let mut input = VecInput::default();
        input
            .read(&mut hrr.into_wire_bytes().as_slice())
            .unwrap();
        let mut retry_flight = Vec::new();
        conn.read_tls(&mut input, &mut retry_flight)
            .handle_all(&mut Vec::new())
            .unwrap();

        let second = client_hello_in(&retry_flight);
        assert_ne!(psk_identity(&second), TICKET);
        assert_eq!(psk_identity(&second), psk_identity(&first));

        fn client_hello_in(bytes: &[u8]) -> ClientHelloPayload {
            let mut reader = Reader::new(bytes);
            while reader.any_left() {
                let record = Record::<Payload<'_>>::read(&mut reader)
                    .unwrap()
                    .into_owned();
                if let Ok(Message {
                    payload:
                        MessagePayload::Handshake {
                            parsed: HandshakeMessagePayload(HandshakePayload::ClientHello(ch)),
                            ..
                        },
                    ..
                }) = Message::try_from(&record)
                {
                    return ch;
                }
            }
            panic!("no ClientHello written");
        }

        fn psk_identity(hello: &ClientHelloPayload) -> &[u8] {
            hello
                .preshared_key_offer
                .as_ref()
                .unwrap()
                .identities[0]
                .identity
                .bytes()
        }

        const TICKET: &[u8] = b"inner name resumption ticket";

        #[derive(Debug)]
        struct CountingRandom;

        impl SecureRandom for CountingRandom {
            fn fill(&self, bytes: &mut [u8]) -> Result<(), GetRandomFailed> {
                static COUNTER: AtomicU8 = AtomicU8::new(0);
                for byte in bytes.iter_mut() {
                    *byte = COUNTER.fetch_add(1, Ordering::Relaxed);
                }
                Ok(())
            }
        }
    }

    fn inner_hello_encoding_for_name(
        name: DnsName<'static>,
        enable_sni: bool,
    ) -> Result<Vec<u8>, Error> {
        let config = EchConfig {
            config: EchConfigPayload::V18(EchConfigContents {
                key_config: HpkeKeyConfig {
                    config_id: 0,
                    kem_id: MockHpke::SUITE.kem,
                    public_key: vec![0; 32].into(),
                    symmetric_cipher_suites: vec![],
                },
                maximum_name_length: 255,
                public_name: DnsName::try_from("public").unwrap(),
                extensions: vec![],
            }),
            suite: &MockHpke,
        };

        EchState::new(
            &config,
            ServerName::from(name.clone()),
            false,
            TEST_PROVIDER.secure_random,
            enable_sni,
        )
        .unwrap()
        .encode_inner_hello(
            &ClientHelloPayload {
                client_version: ProtocolVersion::TLSv1_3,
                random: Random([0u8; 32]),
                session_id: SessionId::empty(),
                cipher_suites: vec![],
                compression_methods: vec![Compression::Null],
                extensions: Box::new(ClientExtensions {
                    server_name: Some(ServerNamePayload::from(&name)),
                    ..Default::default()
                }),
            },
            None,
            None,
        )
    }

    fn dns_name_of_len(mut len: usize) -> DnsName<'static> {
        let mut s = String::new();
        let labels = len.div_ceil(63);
        for _ in 0..labels {
            let chars = Ord::min(len, 63);
            len -= chars;
            for _ in 0..chars {
                s.push('a');
            }
            if len != 0 {
                s.push('.');
            }
        }
        DnsName::try_from(s).unwrap()
    }

    #[derive(Debug)]
    struct MockHpke;

    impl MockHpke {
        const SUITE: HpkeSuite = HpkeSuite {
            kem: HpkeKem::DHKEM_P256_HKDF_SHA256,
            sym: HpkeSymmetricCipherSuite {
                kdf_id: HpkeKdf::HKDF_SHA256,
                aead_id: HpkeAead::AES_128_GCM,
            },
        };
    }

    impl Hpke for MockHpke {
        #[cfg_attr(any(), coverage(off))]
        fn seal(
            &self,
            _info: &[u8],
            _aad: &[u8],
            _plaintext: &[u8],
            _pub_key: &HpkePublicKey,
        ) -> Result<(EncapsulatedSecret, Vec<u8>), Error> {
            todo!()
        }

        fn setup_sealer(
            &self,
            _info: &[u8],
            _pub_key: &HpkePublicKey,
        ) -> Result<(EncapsulatedSecret, Box<dyn HpkeSealer + 'static>), Error> {
            Ok((EncapsulatedSecret(vec![]), Box::new(MockHpkeSealer)))
        }

        #[cfg_attr(any(), coverage(off))]
        fn open(
            &self,
            _enc: &EncapsulatedSecret,
            _info: &[u8],
            _aad: &[u8],
            _ciphertext: &[u8],
            _secret_key: &crate::android_debug_bridge::rustls::crypto::hpke::HpkePrivateKey,
        ) -> Result<Vec<u8>, Error> {
            todo!()
        }

        #[cfg_attr(any(), coverage(off))]
        fn setup_opener(
            &self,
            _enc: &EncapsulatedSecret,
            _info: &[u8],
            _secret_key: &crate::android_debug_bridge::rustls::crypto::hpke::HpkePrivateKey,
        ) -> Result<Box<dyn crate::android_debug_bridge::rustls::crypto::hpke::HpkeOpener + 'static>, Error> {
            todo!()
        }

        #[cfg_attr(any(), coverage(off))]
        fn generate_key_pair(
            &self,
        ) -> Result<(HpkePublicKey, crate::android_debug_bridge::rustls::crypto::hpke::HpkePrivateKey), Error> {
            todo!()
        }

        fn suite(&self) -> HpkeSuite {
            Self::SUITE
        }
    }

    #[derive(Debug)]
    struct MockHpkeSealer;

    impl HpkeSealer for MockHpkeSealer {
        fn seal(&mut self, _aad: &[u8], plaintext: &[u8]) -> Result<Vec<u8>, Error> {

            Ok(vec![0xff; plaintext.len() + 16])
        }
    }

}
};
}

#[allow(clippy::crate_in_macro_def)]
#[macro_export]
macro_rules! adb_t037 {
    ($d:tt) => {
        mod tests {

            use core::time::Duration;
            use std::vec::Vec;

            use crate::android_debug_bridge::pki_types::{CertificateDer, ServerName, UnixTime};

            use super::NoClientSessionStorage;
            use crate::android_debug_bridge::rustls::client::{
                ClientSessionKey, ClientSessionStore, Tls12Session, Tls13ClientSessionInput,
                Tls13Session,
            };
            use crate::android_debug_bridge::rustls::crypto::kx::NamedGroup;
            use crate::android_debug_bridge::rustls::crypto::{
                tls12_suite, tls13_suite, CertificateIdentity, CipherSuite, Identity, TEST_PROVIDER,
            };
            use crate::android_debug_bridge::rustls::msgs::{
                NewSessionTicketExtensions, NewSessionTicketPayloadTls13, SessionId, SizedPayload,
            };
            use crate::android_debug_bridge::rustls::sync::Arc;
            use crate::android_debug_bridge::rustls::tls13::Tls13ProtocolSuite;
            use crate::android_debug_bridge::rustls::verify::VerifiedIdentity;

            #[test]
            fn test_noclientsessionstorage_does_nothing() {
                let c = NoClientSessionStorage {};
                let server_name = ServerName::try_from("example.com").unwrap();
                let key = ClientSessionKey {
                    config_hash: Default::default(),
                    server_name,
                };
                let now = UnixTime::now();

                c.set_kx_hint(key.clone(), NamedGroup::X25519);
                assert_eq!(None, c.kx_hint(&key));

                {
                    c.set_tls12_session(
                        key.clone(),
                        Tls12Session::new(
                            tls12_suite(CipherSuite(0xff12), &TEST_PROVIDER),
                            SessionId::empty(),
                            Arc::new(SizedPayload::empty()),
                            &[0u8; 48],
                            VerifiedIdentity::assertion(Identity::X509(CertificateIdentity {
                                end_entity: CertificateDer::from(&[][..]),
                                intermediates: Vec::new(),
                            })),
                            now,
                            Duration::ZERO,
                            true,
                        ),
                    );
                    assert!(c.tls12_session(&key).is_none());
                    c.remove_tls12_session(&key);
                }

                c.insert_tls13_ticket(
                    key.clone(),
                    Tls13Session::new(
                        &NewSessionTicketPayloadTls13 {
                            lifetime: Duration::ZERO,
                            age_add: 0,
                            nonce: SizedPayload::empty(),
                            ticket: Arc::new(SizedPayload::empty()),
                            extensions: NewSessionTicketExtensions {
                                max_early_data_size: None,
                            },
                        },
                        Tls13ClientSessionInput {
                            suite: Tls13ProtocolSuite::Tcp(tls13_suite(
                                CipherSuite(0xff13),
                                &TEST_PROVIDER,
                            )),
                            peer_identity: VerifiedIdentity::assertion(Identity::X509(
                                CertificateIdentity {
                                    end_entity: CertificateDer::from(&[][..]),
                                    intermediates: Vec::new(),
                                },
                            )),
                            quic_params: None,
                        },
                        &[],
                        now,
                    ),
                );

                assert!(c.take_tls13_ticket(&key).is_none());
            }
        }
    };
}

