#[allow(clippy::crate_in_macro_def)]
#[macro_export]
macro_rules! adb_t054 {
    ($d:tt) => {
        mod tests {

            use std::vec::Vec;

            use crate::android_debug_bridge::rustls::crypto::tls13::{expand, HkdfUsingHmac};

            use super::Hkdf;
            use crate::android_debug_bridge::provider::hmac;

            struct ByteArray<const N: usize>([u8; N]);

            impl<const N: usize> From<[u8; N]> for ByteArray<N> {
                fn from(array: [u8; N]) -> Self {
                    Self(array)
                }
            }

            #[test]
            fn test_case_1() {
                let hkdf = HkdfUsingHmac(&hmac::HMAC_SHA256);
                let ikm = &[0x0b; 22];
                let salt = &[
                    0x00, 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0a, 0x0b, 0x0c,
                ];
                let info: &[&[u8]] = &[
                    &[0xf0, 0xf1, 0xf2],
                    &[0xf3, 0xf4, 0xf5, 0xf6, 0xf7, 0xf8, 0xf9],
                ];

                let output: ByteArray<42> =
                    expand(hkdf.extract_from_secret(Some(salt), ikm).as_ref(), info);

                assert_eq!(
                    &output.0,
                    &[
                        0x3c, 0xb2, 0x5f, 0x25, 0xfa, 0xac, 0xd5, 0x7a, 0x90, 0x43, 0x4f, 0x64,
                        0xd0, 0x36, 0x2f, 0x2a, 0x2d, 0x2d, 0x0a, 0x90, 0xcf, 0x1a, 0x5a, 0x4c,
                        0x5d, 0xb0, 0x2d, 0x56, 0xec, 0xc4, 0xc5, 0xbf, 0x34, 0x00, 0x72, 0x08,
                        0xd5, 0xb8, 0x87, 0x18, 0x58, 0x65
                    ]
                );
            }

            #[test]
            fn test_case_2() {
                let hkdf = HkdfUsingHmac(&hmac::HMAC_SHA256);
                let ikm: Vec<u8> = (0x00u8..=0x4f).collect();
                let salt: Vec<u8> = (0x60u8..=0xaf).collect();
                let info: Vec<u8> = (0xb0u8..=0xff).collect();

                let output: ByteArray<82> = expand(
                    hkdf.extract_from_secret(Some(&salt), &ikm).as_ref(),
                    &[&info],
                );

                assert_eq!(
                    &output.0,
                    &[
                        0xb1, 0x1e, 0x39, 0x8d, 0xc8, 0x03, 0x27, 0xa1, 0xc8, 0xe7, 0xf7, 0x8c,
                        0x59, 0x6a, 0x49, 0x34, 0x4f, 0x01, 0x2e, 0xda, 0x2d, 0x4e, 0xfa, 0xd8,
                        0xa0, 0x50, 0xcc, 0x4c, 0x19, 0xaf, 0xa9, 0x7c, 0x59, 0x04, 0x5a, 0x99,
                        0xca, 0xc7, 0x82, 0x72, 0x71, 0xcb, 0x41, 0xc6, 0x5e, 0x59, 0x0e, 0x09,
                        0xda, 0x32, 0x75, 0x60, 0x0c, 0x2f, 0x09, 0xb8, 0x36, 0x77, 0x93, 0xa9,
                        0xac, 0xa3, 0xdb, 0x71, 0xcc, 0x30, 0xc5, 0x81, 0x79, 0xec, 0x3e, 0x87,
                        0xc1, 0x4c, 0x01, 0xd5, 0xc1, 0xf3, 0x43, 0x4f, 0x1d, 0x87
                    ]
                );
            }

            #[test]
            fn test_case_3() {
                let hkdf = HkdfUsingHmac(&hmac::HMAC_SHA256);
                let ikm = &[0x0b; 22];
                let salt = &[];
                let info = &[];

                let output: ByteArray<42> =
                    expand(hkdf.extract_from_secret(Some(salt), ikm).as_ref(), info);

                assert_eq!(
                    &output.0,
                    &[
                        0x8d, 0xa4, 0xe7, 0x75, 0xa5, 0x63, 0xc1, 0x8f, 0x71, 0x5f, 0x80, 0x2a,
                        0x06, 0x3c, 0x5a, 0x31, 0xb8, 0xa1, 0x1f, 0x5c, 0x5e, 0xe1, 0x87, 0x9e,
                        0xc3, 0x45, 0x4e, 0x5f, 0x3c, 0x73, 0x8d, 0x2d, 0x9d, 0x20, 0x13, 0x95,
                        0xfa, 0xa4, 0xb6, 0x1a, 0x96, 0xc8
                    ]
                );
            }

            #[test]
            fn test_salt_not_provided() {
                let hkdf = HkdfUsingHmac(&hmac::HMAC_SHA384);
                let ikm = &[0x0b; 40];
                let info = &[&b"hell"[..], &b"o"[..]];

                let output: ByteArray<96> =
                    expand(hkdf.extract_from_secret(None, ikm).as_ref(), info);

                assert_eq!(
                    &output.0,
                    &[
                        0xd5, 0x45, 0xdd, 0x3a, 0xff, 0x5b, 0x19, 0x46, 0xd4, 0x86, 0xfd, 0xb8,
                        0xd8, 0x88, 0x2e, 0xe0, 0x1c, 0xc1, 0xa5, 0x48, 0xb6, 0x05, 0x75, 0xe4,
                        0xd7, 0x5d, 0x0f, 0x5f, 0x23, 0x40, 0xee, 0x6c, 0x9e, 0x7c, 0x65, 0xd0,
                        0xee, 0x79, 0xdb, 0xb2, 0x07, 0x1d, 0x66, 0xa5, 0x50, 0xc4, 0x8a, 0xa3,
                        0x93, 0x86, 0x8b, 0x7c, 0x69, 0x41, 0x6b, 0x3e, 0x61, 0x44, 0x98, 0xb8,
                        0xc2, 0xfc, 0x82, 0x82, 0xae, 0xcd, 0x46, 0xcf, 0xb1, 0x47, 0xdc, 0xd0,
                        0x69, 0x0d, 0x19, 0xad, 0xe6, 0x6c, 0x70, 0xfe, 0x87, 0x92, 0x04, 0xb6,
                        0x82, 0x2d, 0x97, 0x7e, 0x46, 0x80, 0x4c, 0xe5, 0x76, 0x72, 0xb4, 0xb8
                    ]
                );
            }

            #[test]
            fn test_output_length_bounds() {
                let hkdf = HkdfUsingHmac(&hmac::HMAC_SHA256);
                let ikm = &[];
                let info = &[];

                let mut output = [0u8; 32 * 255 + 1];
                assert!(hkdf
                    .extract_from_secret(None, ikm)
                    .expand_slice(info, &mut output)
                    .is_err());
            }
        }
    };
}

#[allow(clippy::crate_in_macro_def)]
#[macro_export]
macro_rules! adb_t055 {
    ($d:tt) => {
        mod tests {

            use std::os::unix::fs::PermissionsExt;
            use std::time::{SystemTime, UNIX_EPOCH};
            use std::{env, fs, process};

            use super::*;

            #[test]
            fn test_env_var_is_not_set() {
                let mut inner = KeyLogFileInner::new(None);
                assert!(inner.try_write("label", b"random", b"secret").is_ok());
            }

            #[test]
            fn test_env_var_cannot_be_opened() {
                let mut inner = KeyLogFileInner::new(Some("/dev/does-not-exist".into()));
                assert!(inner.try_write("label", b"random", b"secret").is_ok());
            }

            #[test]
            fn test_env_var_cannot_be_written() {
                #[cfg(target_os = "linux")]
                const UNWRITABLE_FILE: &str = "/dev/full";

                #[cfg(target_os = "macos")]
                const UNWRITABLE_FILE: &str = "/dev/urandom";

                let mut inner = KeyLogFileInner::new(Some(UNWRITABLE_FILE.into()));
                assert!(inner.try_write("label", b"random", b"secret").is_err());
            }

            #[test]
            fn test_created_file_has_owner_only_permissions() {
                let path = env::temp_dir().join(format!(
                    "rustls-keylog-perm-{}-{}",
                    process::id(),
                    SystemTime::now()
                        .duration_since(UNIX_EPOCH)
                        .unwrap()
                        .as_nanos()
                ));
                let _ = fs::remove_file(&path);

                let inner = KeyLogFileInner::new(Some(path.clone().into()));
                assert!(inner.file.is_some(), "key log file should open");

                let mode = fs::metadata(&path).expect("metadata").permissions().mode() & 0o777;
                let _ = fs::remove_file(&path);

                assert_eq!(
                    mode, 0o600,
                    "SSLKEYLOGFILE must be created with mode 0o600, got {mode:#o}"
                );
            }
        }
    };
}

